  const ticketLabel = ticket ? ` · ${getTicketDisplayProduct(ticket) || ticket.product || "회원권"}` : "";
  return `${member?.name || "회원"}${ticketLabel}: ${[...new Set(changed)].join(", ") || "입력값"}`;
