function settlementRuleFor(coachName) {
  return coachSettlementRules.find((rule) => rule.coach === coachName) || coachSettlementRules[0];
}

function vatExclusiveSettlementAmount(amount) {
  return Math.max(0, Math.round((Number(amount) || 0) * 10 / 11));
}

function settlementBaseAmountForBilling(billing = {}) {
  const explicitBase = Number(billing.settlementBaseAmount) || 0;
  if (explicitBase > 0) return explicitBase;
  const paidAmount = Number(billing.finalAmount || billing.amount) || 0;
  const method = String(billing.method || "").toLowerCase();
  return method.includes("card") ? vatExclusiveSettlementAmount(paidAmount) : paidAmount;
}

function settlementCoachNameFor(item) {
  if (item.forceActualCoach && item.actualCoach) return item.actualCoach;
  if (!item.actualCoach || item.actualCoach === item.coach) return item.coach;
  const actualRule = settlementRuleFor(item.actualCoach);
  if (actualRule.substitute === "originalCoach") return item.coach;
  return item.actualCoach;
}

function settlementAmountFor(item) {
  if (item.linkedTicket === false) return 0;
  if (Number.isFinite(Number(item.fixedSettlementAmount))) return Math.max(0, Math.round(Number(item.fixedSettlementAmount)));
  const settlementCoach = settlementCoachNameFor(item);
  const rule = settlementRuleFor(settlementCoach);
  const completedLessons = Math.max(0, Number(item.lessonCount) || 0);
  if (!completedLessons || !rule) return 0;
  if (rule.method === "hourly") {
    const minutes = Math.max(0, Number(item.minutes || item.durationMinutes) || 0);
    const hourlyRate = Math.max(0, Number(rule.hourly) || 0);
    if (!minutes || !hourlyRate) return 0;
    return Math.round((minutes / 60) * hourlyRate * completedLessons);
  }
  const totalLessons = Math.max(completedLessons, Number(item.totalLessons) || completedLessons);
  const baseAmount = Number(rule.cardBase === "paid" ? item.paidAmount : item.settlementBase) || 0;
  if (rule.calculationMode === "monthly_payment") {
    return Math.round(baseAmount * (Number(rule.ratio) || 0));
  }
  const perLessonBase = baseAmount / totalLessons;
  return Math.round(perLessonBase * completedLessons * (Number(rule.ratio) || 0));
}

function settlementRecordProgressByTicket(indexes = {}) {
  const ticketById = indexes.ticketById || new Map();
  const assignmentByLesson = indexes.assignmentByLesson || new Map();
  const progressByTicket = new Map();
  (adminLiveDataState.lessonRecords || []).forEach((record) => {
    const linkedLesson = Array.isArray(record.tn_lessons) ? record.tn_lessons[0] : record.tn_lessons || {};
    const ticketId = String(record.deducted_ticket_id || linkedLesson.member_ticket_id || "");
    const ticket = ticketById.get(ticketId);
    if (!ticketId || !ticket) return;
    const sessions = Math.max(0, Number(record.deducted_sessions) || 0);
    if (!sessions) return;
    const coachRoleId = String(record.coach_role_id || "");
    const durationMinutes = Math.max(0, Number(linkedLesson.duration_minutes || ticket.durationMinutes) || 0);
    const progress = progressByTicket.get(ticketId) || {
      recordedSessions: 0,
      byCoachRole: new Map(),
      substituteGroups: new Map(),
    };
    progress.recordedSessions += sessions;
    const coachProgress = progress.byCoachRole.get(coachRoleId) || { sessions: 0, minutes: 0 };
    coachProgress.sessions += sessions;
    coachProgress.minutes += sessions * durationMinutes;
    progress.byCoachRole.set(coachRoleId, coachProgress);

    const originalCoachRoleId = String(ticket.coachRoleId || "");
    if (coachRoleId && originalCoachRoleId && coachRoleId !== originalCoachRoleId) {
      const assignment = assignmentByLesson.get(String(record.lesson_id || ""));
      const mode = assignment?.settlement_mode || "actual_coach";
      const hourlyAmount = mode === "hourly" ? Math.max(0, Number(assignment?.hourly_amount) || 0) : 0;
      const key = `${coachRoleId}|${mode}|${hourlyAmount}`;
      const substitute = progress.substituteGroups.get(key) || {
        coachRoleId,
        mode,
        hourlyAmount,
        sessions: 0,
        minutes: 0,
      };
      substitute.sessions += sessions;
      substitute.minutes += sessions * durationMinutes;
      progress.substituteGroups.set(key, substitute);
    }
    progressByTicket.set(ticketId, progress);
  });
  return progressByTicket;
}

function oneDayBookingForBilling(billing = {}) {
  const bookingId = String(billing.oneDayBookingId || "");
  if (!bookingId) return null;
  return lessons.find((lesson) => (
    lesson.oneDayBooking
    && String(lesson.serverOneDayBookingId || "") === bookingId
  )) || null;
}

function settlementRowsForBilling(billing, indexes = {}) {
  const ticket = indexes.ticketById?.get(String(billing.ticketId || ""))
    || [...tickets, ...expiredTickets].find((item) => item.serverTicketId === billing.ticketId || item.id === billing.ticketId)
    || {};
  const ticketId = ticket.serverTicketId || ticket.id;
  const oneDayBooking = oneDayBookingForBilling(billing);
  const oneDayLinked = Boolean(billing.oneDayBookingId);
  const oneDayCoach = oneDayBooking ? getCoachName(oneDayBooking.coachId || "") : "원데이 예약";
  const base = {
    member: billing.member,
    coach: ticketId ? getCoachName(ticket.coachId || "") : oneDayLinked ? oneDayCoach : "회원권 미연결",
    linkedTicket: Boolean(ticketId || oneDayLinked),
    oneDayLinked,
    paidAmount: Number(billing.finalAmount || billing.amount) || 0,
    settlementBase: settlementBaseAmountForBilling(billing),
    paymentMethod: String(billing.method || "").toLowerCase().includes("card") ? "카드" : "현금",
    discount: Number(billing.discountAmount) > 0 ? `할인 ${money.format(billing.discountAmount)}원` : "할인 없음",
    totalLessons: oneDayLinked ? 1 : Number(ticket.total) || 0,
    minutes: oneDayBooking ? Number(oneDayBooking.durationMinutes) || 20 : Number(ticket.durationMinutes) || 20,
  };
  if (indexes.recordProgressByTicket) {
    if (!ticketId) return [{
      ...base,
      actualCoach: base.coach,
      lessonCount: oneDayBooking?.status === "completed" ? 1 : 0,
      summaryPaidAmount: base.paidAmount,
    }];
    const progress = indexes.recordProgressByTicket.get(String(ticketId)) || {
      recordedSessions: 0,
      byCoachRole: new Map(),
      substituteGroups: new Map(),
    };
    const originalCoachRoleId = String(ticket.coachRoleId || "");
    const originalProgress = progress.byCoachRole.get(originalCoachRoleId) || { sessions: 0, minutes: 0 };
    const fallbackSessions = Math.max(0, (Number(ticket.used) || 0) - (Number(progress.recordedSessions) || 0));
    const lessonCount = Math.min(
      Math.max(0, Number(ticket.total) || 0),
      Math.max(0, Number(originalProgress.sessions) || 0) + fallbackSessions,
    );
    const originalMinutes = Math.max(0, Number(originalProgress.minutes) || 0)
      + fallbackSessions * Math.max(0, Number(base.minutes) || 0);
    const originalRule = settlementRuleFor(base.coach);
    const ownRow = {
      ...base,
      actualCoach: base.coach,
      lessonCount,
      minutes: lessonCount ? originalMinutes / lessonCount : base.minutes,
      sessionKey: `${ticketId}|${originalCoachRoleId}|own`,
      summaryPaidAmount: base.paidAmount,
      fixedSettlementAmount: originalRule?.method === "hourly"
        ? Math.round(originalMinutes / 60 * Math.max(0, Number(originalRule.hourly) || 0))
        : undefined,
    };
    const substituteRows = [...progress.substituteGroups.values()].map((substitute) => {
      const actualCoach = coachNameForRoleId(substitute.coachRoleId);
      const actualRule = settlementRuleFor(actualCoach);
      const fixedSettlementAmount = substitute.mode === "none"
        ? 0
        : substitute.mode === "hourly"
          ? Math.round(substitute.minutes / 60 * substitute.hourlyAmount)
          : actualRule?.method === "hourly"
            ? Math.round(substitute.minutes / 60 * Math.max(0, Number(actualRule.hourly) || 0))
            : undefined;
      return {
        ...base,
        actualCoach,
        forceActualCoach: true,
        lessonCount: substitute.sessions,
        minutes: substitute.sessions ? substitute.minutes / substitute.sessions : base.minutes,
        sessionKey: `${ticketId}|${substitute.coachRoleId}|${substitute.mode}|${substitute.hourlyAmount}`,
        summaryPaidAmount: 0,
        fixedSettlementAmount,
        substituteHourlyRate: substitute.mode === "hourly" ? substitute.hourlyAmount : 0,
        substituteSettlementMode: substitute.mode,
      };
    });
    return [ownRow, ...substituteRows];
  }
  const completedLessons = indexes.completedLessonsByTicket?.get(String(ticketId || ""))
    || (adminLiveDataState.lessons || []).filter((lesson) => (
      String(lesson.ticketId || "") === String(ticketId || "")
      && lesson.serverStatus === "completed"
    ));
  if (!completedLessons.length) return [{ ...base, actualCoach: base.coach, lessonCount: Number(ticket.used) || 0 }];

  const assignments = adminLiveDataState.substituteAssignments || [];
  const grouped = new Map();
  completedLessons.forEach((lesson) => {
    const assignment = indexes.assignmentByLesson?.get(String(lesson.serverLessonId || ""))
      || assignments.find((item) => (
        String(item.lesson_id) === String(lesson.serverLessonId)
        && ["assigned", "completed"].includes(item.status)
      ));
    const actualCoach = assignment
      ? coachNameForRoleId(assignment.substitute_coach_role_id)
      : getCoachName(lesson.coachId || ticket.coachId || "");
    const mode = assignment?.settlement_mode || "actual_coach";
    const key = `${actualCoach}|${mode}|${assignment?.hourly_amount || 0}`;
    const row = grouped.get(key) || {
      ...base,
      actualCoach,
      forceActualCoach: Boolean(assignment),
      lessonCount: 0,
      fixedSettlementAmount: ["hourly", "none"].includes(mode) ? 0 : undefined,
      substituteHourlyRate: mode === "hourly" ? Number(assignment?.hourly_amount || 0) : 0,
      substituteSettlementMode: mode,
    };
    row.lessonCount += 1;
    if (mode === "hourly") {
      row.fixedSettlementAmount += Math.round((Number(lesson.durationMinutes || base.minutes) / 60) * Number(assignment.hourly_amount || 0));
    }
    grouped.set(key, row);
  });
  const missingCompleted = Math.max(0, (Number(ticket.used) || 0) - completedLessons.length);
  if (missingCompleted) {
    const key = `${base.coach}|actual_coach|0`;
    const row = grouped.get(key) || { ...base, actualCoach: base.coach, lessonCount: 0 };
    row.lessonCount += missingCompleted;
    grouped.set(key, row);
  }
  return [...grouped.values()];
}

function settlementOrphanSubstituteRows(indexes = {}, billedTicketIds = new Set()) {
  const rows = [];
  (indexes.recordProgressByTicket || new Map()).forEach((progress, ticketId) => {
    if (billedTicketIds.has(String(ticketId)) || !progress?.substituteGroups?.size) return;
    const ticket = indexes.ticketById?.get(String(ticketId));
    if (!ticket) return;
    const syntheticBilling = {
      member: ticket.member || "대타 수업",
      ticketId,
      amount: 0,
      finalAmount: 0,
      method: "cash",
    };
    rows.push(...settlementRowsForBilling(syntheticBilling, indexes).slice(1));
  });
  return rows;
}

function renderCoachSettlementPreview() {
  if (!["billing", "settings"].includes(state.view)) return;
  const previewRows = $("#coachSettlementPreviewRows");
  if (previewRows) {
    const ticketById = new Map();
    [...tickets, ...expiredTickets, ...(adminLiveDataState.settlementTickets || [])].forEach((ticket) => {
      if (ticket.id) ticketById.set(String(ticket.id), ticket);
      if (ticket.serverTicketId) ticketById.set(String(ticket.serverTicketId), ticket);
    });
    const completedLessonsByTicket = new Map();
    (adminLiveDataState.lessons || []).forEach((lesson) => {
      if (lesson.serverStatus !== "completed" || !lesson.ticketId) return;
      const key = String(lesson.ticketId);
      const rows = completedLessonsByTicket.get(key) || [];
      rows.push(lesson);
      completedLessonsByTicket.set(key, rows);
    });
    const assignmentByLesson = new Map();
    (adminLiveDataState.substituteAssignments || []).forEach((assignment) => {
      if (!assignment.lesson_id || !["assigned", "completed"].includes(assignment.status)) return;
      assignmentByLesson.set(String(assignment.lesson_id), assignment);
    });
    const recordProgressByTicket = settlementRecordProgressByTicket({ ticketById, assignmentByLesson });
    const monthBillings = billings
      .filter((billing) => billing.status === "paid" && billingMatchesMonth(billing, state.billingMonth));
    const settlementIndexes = {
        ticketById,
        completedLessonsByTicket,
        assignmentByLesson,
        recordProgressByTicket,
      };
    const billedTicketIds = new Set(monthBillings.map((billing) => String(billing.ticketId || "")).filter(Boolean));
    const liveSettlementRows = monthBillings
      .flatMap((billing) => settlementRowsForBilling(billing, settlementIndexes));
    liveSettlementRows.push(...settlementOrphanSubstituteRows(settlementIndexes, billedTicketIds));
    const previewItems = adminDemoMode ? coachSettlementPreview : liveSettlementRows;
    const settlementSummary = $("#coachSettlementSummary");
    if (settlementSummary) {
      const summaries = new Map();
      const countedSessionKeys = new Set();
      previewItems.forEach((item) => {
        const coach = item.linkedTicket === false ? "회원권 미연결" : settlementCoachNameFor(item);
        const current = summaries.get(coach) || {
          coach,
          paidAmount: 0,
          completedLessons: 0,
          settlementAmount: 0,
          issueCount: 0,
        };
        current.paidAmount += Number(item.summaryPaidAmount ?? item.paidAmount) || 0;
        if (!item.sessionKey || !countedSessionKeys.has(item.sessionKey)) {
          current.completedLessons += Number(item.lessonCount) || 0;
          if (item.sessionKey) countedSessionKeys.add(item.sessionKey);
        }
        current.settlementAmount += settlementAmountFor(item);
        if (item.linkedTicket === false) current.issueCount += 1;
        summaries.set(coach, current);
      });
      settlementSummary.innerHTML = [...summaries.values()]
        .sort((left, right) => left.coach === "회원권 미연결" ? -1 : right.settlementAmount - left.settlementAmount)
        .map((item) => `
          <article>
            <span>${escapeHtml(item.coach)}</span>
            <strong>${money.format(item.settlementAmount)}원</strong>
            <small>완료 ${item.completedLessons}회 · 결제 ${money.format(item.paidAmount)}원${item.issueCount ? ` · 연결 확인 ${item.issueCount}건` : ""}</small>
          </article>`)
        .join("") || '<article><span>정산 내역</span><strong>0원</strong><small>선택한 달의 결제 내역이 없습니다.</small></article>';
    }
    state.settlementPage = normalizeDashboardPage(previewItems.length, state.settlementPage, billingPageSize);
    const visiblePreviewItems = previewItems.slice(
      state.settlementPage * billingPageSize,
      (state.settlementPage + 1) * billingPageSize,
    );
    previewRows.innerHTML = visiblePreviewItems
      .map((item) => {
        const settlementCoach = settlementCoachNameFor(item);
        const rule = settlementRuleFor(settlementCoach);
        const transferred = item.coach !== item.actualCoach;
        const ruleLabel = item.substituteSettlementMode === "none"
          ? "정산 없음"
          : item.substituteHourlyRate
          ? `대타 시급 ${money.format(item.substituteHourlyRate)}원`
          : rule.method === "hourly" ? `시급 ${money.format(rule.hourly)}원` : `${Math.round(rule.ratio * 10)}:${10 - Math.round(rule.ratio * 10)}`;
        return `
          <tr>
            <td><strong>${item.member}</strong><br><small>${item.lessonCount}/${item.totalLessons || item.lessonCount}회 완료</small></td>
            <td class="${item.linkedTicket === false ? "payment-link-warning" : ""}">${item.coach}${item.linkedTicket === false ? "<br><small>회원권 연결 후 정산 가능</small>" : transferred ? `<br><small>대타 ${item.actualCoach} · 정산 ${settlementCoach}</small>` : "<br><small>담당 코치 진행</small>"}</td>
            <td>${money.format(item.paidAmount)}원<br><small>${item.paymentMethod} · ${item.discount}</small></td>
            <td><strong>${money.format(item.settlementBase)}원</strong><br><small>${item.paymentMethod === "카드" ? "부가세 제외 현금가" : "실결제 기준"}</small></td>
            <td>${ruleLabel}<br><small>${transferred ? "대타 이관 적용" : "기본 정산"}</small></td>
            <td><strong>${money.format(settlementAmountFor(item))}원</strong></td>
          </tr>`;
      })
      .join("") || '<tr><td colspan="6" class="empty-text">실제 결제 내역이 없습니다.</td></tr>';
    renderDashboardPager(
      "#coachSettlementPreviewPager",
      previewItems.length,
      state.settlementPage,
      "settlement",
      billingPageSize,
    );
  }

}

function paymentMethodLabel(method = "") {
  const value = String(method || "").trim();
  const normalized = value.toLowerCase().replace(/[^a-z0-9]/g, "");
  const labels = {
    card: "카드",
    tosspay: "토스페이",
    naverpay: "네이버페이",
    kakaopay: "카카오페이",
    easypay: "간편결제",
    transfer: "계좌이체",
    banktransfer: "계좌이체",
    cash: "현금",
    bank: "계좌이체",
    manual: "관리자 입력",
    membershiptransfer: "회원권 양도",
    legacy: "기존 기록",
    virtualaccount: "가상계좌",
    mobile: "휴대폰결제",
  };
  return labels[normalized] || value.replaceAll("결제청구", "결제요청").replaceAll("청구서", "결제요청");
}

function adminPaymentCancelReady() {
  const client = window.TennisNoteDataClient;
  return Boolean(client?.readiness?.().ready && client.getSession?.()?.access_token && adminImportAuthState.profile?.role === "admin");
}

function adminPaymentCancelBlockedMessage() {
  const client = window.TennisNoteDataClient;
  if (!client?.readiness?.().ready) return "Supabase 연결값 설정 후 결제취소를 사용할 수 있습니다.";
  if (!client.getSession?.()?.access_token) return "관리자 로그인 후 결제취소할 수 있습니다.";
  if (adminImportAuthState.loading) return "관리자 권한을 확인하는 중입니다.";
  if (adminImportAuthState.user && adminImportAuthState.profile?.role !== "admin") return "관리자 권한 계정만 결제취소할 수 있습니다.";
  return "관리자 권한 확인 후 결제취소할 수 있습니다.";
}

function paymentCancelButtonFor(index, label = "결제취소") {
  const item = billings[index] || {};
  const context = `${item.member || "회원"} · ${item.item || "결제"} · ${label}`;
  if (adminPaymentCancelReady()) {
    return `<button class="small-button danger-action" type="button" data-cancel-payment="${index}" aria-label="${escapeHtml(context)}" title="${escapeHtml(context)}">${label}</button>`;
  }
  return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}" title="${escapeHtml(adminPaymentCancelBlockedMessage())}">관리자 로그인 필요</button>`;
}

function paymentFullCancelAmount(item = {}) {
  return Math.max(0, Number(item.finalAmount || item.amount || 0));
}

function isManualCashRefundItem(item = {}) {
  return ["bank_transfer", "cash", "account_transfer", "transfer"].includes(String(item.method || "").trim().toLowerCase());
}

function paymentFullCancelButtonFor(item, index) {
  const amount = paymentFullCancelAmount(item);
  if (isManualCashRefundItem(item)) return "";
  const context = `${item?.member || "회원"} · ${item?.item || "결제"} · PG 전액 결제취소 ${money.format(amount)}원`;
  if (!item?.providerPaymentId || amount <= 0) {
    return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}" title="서버 결제번호와 결제금액이 필요합니다.">PG 전액 결제취소</button>`;
  }
  if (paymentCancelInFlight.has(item.providerPaymentId)) {
    return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}">취소 처리 중</button>`;
  }
  if (adminPaymentCancelReady()) {
    return `<button class="small-button danger-action" type="button" data-cancel-payment="${index}" aria-label="${escapeHtml(context)}" title="테스트·오결제·당일 미사용 결제를 PG에서 전액 취소합니다.">PG 전액 결제취소</button>`;
  }
  return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}" title="${escapeHtml(adminPaymentCancelBlockedMessage())}">관리자 로그인 필요</button>`;
}

function paymentRefundButtonFor(item, index) {
  const context = `${item?.member || "회원"} · ${item?.item || "결제"} · 환불 계산`;
  if (!item?.providerPaymentId) {
    return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}" title="서버 결제번호가 필요합니다.">환불 계산</button>`;
  }
  if (adminPaymentCancelReady()) {
    return `<button class="small-button danger-action" type="button" data-refund-payment="${index}" aria-label="${escapeHtml(context)}" title="${escapeHtml(context)}">환불 계산</button>`;
  }
  return `<button class="small-button danger-action" type="button" disabled aria-label="${escapeHtml(context)}" title="${escapeHtml(adminPaymentCancelBlockedMessage())}">관리자 로그인 필요</button>`;
}

function renderPaymentAdminGateStatus() {
  const target = $("#paymentAdminGateStatus");
  if (!target) return;
  const ready = adminPaymentCancelReady();
  const tone = ready ? "good" : adminImportAuthState.loading ? "neutral" : "warn";
  target.innerHTML = `
    <article class="payment-admin-gate-card ${tone}">
      <div>
        <strong>${ready ? "결제취소·환불 가능" : "결제취소·환불 잠금"}</strong>
        <span>${escapeHtml(ready ? "관리자 로그인과 권한이 확인되어 결제취소와 환불 계산을 진행할 수 있습니다." : adminPaymentCancelBlockedMessage())}</span>
      </div>
      ${badge(tone, ready ? "관리자 확인됨" : "관리자 확인 필요")}
    </article>`;
}

const staleReadyPaymentMs = 60 * 60 * 1000;

function paymentCreatedAtMs(item = {}) {
  const candidates = [item.createdAt, item.created_at, item.requestedAt, item.paidAt, item.verifiedAt];
  for (const value of candidates) {
    if (!value) continue;
    const timestamp = Date.parse(String(value));
    if (Number.isFinite(timestamp)) return timestamp;
  }
  return 0;
}

function isStaleReadyPayment(item = {}) {
  if (item.status !== "server_ready") return false;
  const createdAt = paymentCreatedAtMs(item);
  return Boolean(createdAt && Date.now() - createdAt > staleReadyPaymentMs);
}

function paymentDisplayStatus(item = {}) {
  if (isStaleReadyPayment(item)) {
    return {
      status: "warn",
      label: "오래된 결제 대기",
      detail: "결제창 생성 후 1시간 이상 완료 확인이 없습니다. 자동 취소하지 말고 결제 상태를 확인하세요.",
    };
  }
  return {
    status: item.status,
    label: item.statusLabel,
    detail: "",
  };
}

function billingFilterGroup(item = {}) {
  if (["cancelled", "refunded", "refund_manual_pending", "refund_processing", "refund_reconcile", "cancel_reconcile"].includes(item.status)) return "refund";
  if (isStaleReadyPayment(item)) return "action";
  if (["server_ready", "unverified"].includes(item.status)) return "verifying";
  if (item.status === "paid") return "done";
  return "action";
}

function billingEffectiveDate(item = {}) {
  const candidates = [
    item.paidAt,
    item.paid_at,
    item.verifiedAt,
    item.verified_at,
    item.requestedAt,
    item.requested_at,
    item.createdAt,
    item.created_at,
  ];
  for (const value of candidates) {
    const text = String(value || "");
    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
    const parsed = Date.parse(text);
    if (Number.isFinite(parsed)) return adminLocalDateKey(new Date(parsed));
    if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.slice(0, 10);
  }
  return "";
}

function billingMatchesMonth(item, month) {
  if (!month) return true;
  return billingIncludedInRevenue(item) && billingEffectiveMonth(item) === month;
}

function billingIncludedInRevenue(item = {}) {
  return String(item.revenueAttributionStatus || item.revenue_attribution_status || "included") === "included";
}

function billingEffectiveMonth(item = {}) {
  const revenueMonth = String(item.revenueMonth || item.revenue_month || "").slice(0, 7);
  return /^\d{4}-\d{2}$/.test(revenueMonth) ? revenueMonth : billingEffectiveDate(item).slice(0, 7);
}

function billingMonthLabel(month) {
  const match = /^(\d{4})-(\d{2})$/.exec(String(month || ""));
  return match ? `${Number(match[1])}년 ${Number(match[2])}월 회원권 매출` : "선택 월 회원권 매출";
}

function linkedTicketForBilling(item = {}) {
  return [...tickets, ...expiredTickets].find((ticket) => (
    String(ticket.serverTicketId || ticket.id || "") === String(item.ticketId || "")
  )) || null;
}

function billingMembershipDetail(item = {}) {
  if (item.oneDayBookingId) {
    const booking = oneDayBookingForBilling(item);
    if (!booking) return '<strong>원데이 예약</strong><br><small>결제와 예약이 연결됐습니다.</small>';
    const coach = getCoachName(booking.coachId || "") || "코치 확인 필요";
    const schedule = [booking.lessonDate, booking.time].filter(Boolean).join(" ");
    const status = booking.status === "completed" ? "수업 완료" : "예약 완료";
    return `<strong>원데이 예약</strong><br><small>${escapeHtml(coach)}${schedule ? ` · ${escapeHtml(schedule)}` : ""} · ${status}</small>`;
  }
  const ticket = linkedTicketForBilling(item);
  if (!ticket) return '<span class="payment-link-warning">회원권 연결 필요</span>';
  const product = getTicketDisplayProduct(ticket) || ticket.product || "회원권";
  const coach = getCoachName(ticket.coachId || "") || "코치 미지정";
  return `<strong>${escapeHtml(product)}</strong><br><small>${escapeHtml(coach)} · ${Number(ticket.used) || 0}/${Number(ticket.total) || 0}회 진행 · 잔여 ${Number(ticket.remaining) || 0}회</small>`;
}

function paymentAuditDateTimeLabel(value = "") {
  const date = new Date(value);
  if (!value || Number.isNaN(date.getTime())) return "";
  return date.toLocaleString("ko-KR", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function paymentCancellationAuditDetail(item = {}) {
  if (!["cancelled", "refunded"].includes(item.status)) return "";
  const amount = Number(item.refundedAmount || (item.status === "cancelled" ? paymentFullCancelAmount(item) : 0));
  const parts = [];
  if (amount > 0) parts.push(`${money.format(amount)}원`);
  if (item.refundReason) parts.push(`사유: ${item.refundReason}`);
  const completedAt = paymentAuditDateTimeLabel(item.refundedAt);
  if (completedAt) parts.push(completedAt);
  return parts.join(" · ");
}

function paymentCancellationAuditLog(item = {}) {
  const detail = paymentCancellationAuditDetail(item);
  if (!detail) return "";
  return `${item.member || "회원"} · ${item.item || "결제"} · ${item.status === "refunded" ? "환불" : "PG 전액취소"} · ${detail}`;
}

function renderBilling() {
  syncSharedPaymentRequests();
  state.billingFilter = ["action", "verifying", "done", "refund"].includes(state.billingFilter) ? state.billingFilter : "action";
  state.billingMonth = /^\d{4}-\d{2}$/.test(state.billingMonth)
    ? state.billingMonth
    : adminLocalDateKey(new Date()).slice(0, 7);
  const branchBillings = operationBranchBillings();
  const monthBillings = branchBillings.filter((item) => billingMatchesMonth(item, state.billingMonth));
  const pendingRequests = monthBillings.filter((item) => item.status === "draft");
  const pendingChecks = monthBillings.filter((item) => item.status === "check" || item.status === "unverified");
  const staleReadyPayments = monthBillings.filter(isStaleReadyPayment);
  const rechargeTargets = operationBranchTickets().filter((ticket) => ticket.remaining <= 1);
  const monthPaidBillings = monthBillings.filter((item) => item.status === "paid");
  const monthPaidAmount = monthPaidBillings.reduce((sum, item) => sum + Number(item.finalAmount || item.amount || 0), 0);
  const actualPaidBillings = branchBillings.filter((item) => (
    item.status === "paid"
    && billingIncludedInRevenue(item)
    && billingEffectiveDate(item).slice(0, 7) === state.billingMonth
  ));
  const excludedDuplicateBillings = branchBillings.filter((item) => (
    String(item.revenueAttributionStatus || "") === "duplicate_excluded"
    && (billingEffectiveMonth(item) === state.billingMonth || billingEffectiveDate(item).slice(0, 7) === state.billingMonth)
  ));
  const excludedCohortBillings = branchBillings.filter((item) => (
    String(item.revenueAttributionStatus || "") === "cohort_excluded"
    && (billingEffectiveMonth(item) === state.billingMonth || billingEffectiveDate(item).slice(0, 7) === state.billingMonth)
  ));
  const actualPaidAmount = actualPaidBillings.reduce((sum, item) => sum + Number(item.finalAmount || item.amount || 0), 0);

  $("#billingRequestCount").textContent = `${pendingRequests.length}건`;
  $("#billingCheckCount").textContent = `${pendingChecks.length + staleReadyPayments.length}\uAC74`;
  $("#ticketRechargeCount").textContent = `${rechargeTargets.length}명`;
  if ($("#billingMonthFilter")) $("#billingMonthFilter").value = state.billingMonth;
  if ($("#billingMonthTotalLabel")) $("#billingMonthTotalLabel").textContent = billingMonthLabel(state.billingMonth);
  if ($("#billingMonthPaidAmount")) $("#billingMonthPaidAmount").textContent = `${money.format(monthPaidAmount)}원`;
  if ($("#billingMonthPaidCount")) $("#billingMonthPaidCount").textContent = `매출 귀속 ${monthPaidBillings.length}건`;
  if ($("#billingActualPaidSummary")) {
    const exclusionLabels = [
      excludedDuplicateBillings.length ? `중복 근거 ${excludedDuplicateBillings.length}건` : "",
      excludedCohortBillings.length ? `확정 코호트 외 ${excludedCohortBillings.length}건` : "",
    ].filter(Boolean);
    $("#billingActualPaidSummary").textContent = `실제 결제일 기준 ${actualPaidBillings.length}건 · ${money.format(actualPaidAmount)}원${exclusionLabels.length ? ` · ${exclusionLabels.join(" · ")} 제외` : ""}`;
  }
  renderPaymentAdminGateStatus();
  renderPaymentChargeAudit();
  const billingGroups = { action: [], verifying: [], done: [], refund: [] };
  monthBillings.forEach((item) => billingGroups[billingFilterGroup(item)]?.push(item));
  $$('[data-billing-count]').forEach((count) => {
    count.textContent = String(billingGroups[count.dataset.billingCount]?.length || 0);
  });
  $$('[data-billing-filter]').forEach((button) => button.classList.toggle("is-active", button.dataset.billingFilter === state.billingFilter));

  const syncTarget = $("#serverPaymentSyncStatus");
  if (syncTarget) {
    syncTarget.innerHTML = `
      <div class="payment-sync-card ${serverPaymentSyncState.tone}">
        <span>${serverPaymentSyncState.message}</span>
        ${badge(serverPaymentSyncState.tone, serverPaymentSyncState.loading ? "불러오는 중" : serverPaymentSyncState.loaded ? "확인됨" : "대기")}
      </div>`;
  }

  const filteredBillings = billingGroups[state.billingFilter] || [];
  state.billingPage = normalizeDashboardPage(filteredBillings.length, state.billingPage, billingPageSize);
  const visibleBillings = filteredBillings.slice(
    state.billingPage * billingPageSize,
    (state.billingPage + 1) * billingPageSize,
  );
  $("#billingRows").innerHTML = visibleBillings.length ? visibleBillings
    .map(
      (item) => {
        const index = billings.indexOf(item);
        const displayStatus = paymentDisplayStatus(item);
        return `
        <tr>
          <td>${item.member}<br><small>${paymentEnvironmentBadge(item)}</small></td>
          <td>${billingMembershipDetail(item)}<details class="payment-source-details"><summary>결제 원본 보기</summary><span>${escapeHtml(item.item || "결제")}${item.providerPaymentId ? ` · ${escapeHtml(item.providerPaymentId)}` : ""}${item.source ? ` · ${escapeHtml(paymentSourceText(item))}` : ""}</span></details></td>
          <td>${escapeHtml(billingEffectiveDate(item) || "일자 미입력")}${billingEffectiveMonth(item) ? `<br><small>매출 귀속 ${escapeHtml(billingEffectiveMonth(item))}</small>` : ""}</td>
          <td>${money.format(item.amount)}원${item.discountTitle ? `<br><small>${escapeHtml(item.discountTitle)} · ${money.format(item.discountAmount || 0)}원 할인${item.originalAmount ? ` · 원가 ${money.format(item.originalAmount)}원` : ""}</small>` : ""}</td>
          <td>${paymentMethodLabel(item.method)}</td>
          <td>${badge(displayStatus.status, displayStatus.label)}${displayStatus.detail ? `<br><small>${escapeHtml(displayStatus.detail)}</small>` : ""}${paymentCancellationAuditDetail(item) ? `<br><small>${escapeHtml(paymentCancellationAuditDetail(item))}</small>` : ""}</td>
          <td>
            ${paymentActionFor(item, index)}
          </td>
        </tr>`;
      },
    )
    .join("") : '<tr><td colspan="7" class="empty-text">선택한 달과 상태의 결제 내역이 없습니다.</td></tr>';
  renderDashboardPager("#billingPager", filteredBillings.length, state.billingPage, "billing", billingPageSize);

  state.rechargePage = normalizeDashboardPage(rechargeTargets.length, state.rechargePage, billingPageSize);
  const visibleRechargeTargets = rechargeTargets.slice(
    state.rechargePage * billingPageSize,
    (state.rechargePage + 1) * billingPageSize,
  );
  $("#rechargeRows").innerHTML = visibleRechargeTargets.length ? visibleRechargeTargets
    .map(
      (ticket, index) => `
        <tr>
          <td>${ticket.member}</td>
          <td>${ticket.product}</td>
          <td><strong>${ticket.remaining}회</strong></td>
          <td>${ticket.remaining === 0 ? "즉시 충전 필요" : "다음 수업 전 안내"}</td>
          <td><button class="small-button" type="button" data-renew-ticket="${escapeHtml(ticket.serverTicketId || "")}" data-renew-member="${escapeHtml(ticket.member)}">연장 등록</button></td>
        </tr>`,
    )
    .join("") : '<tr><td colspan="5" class="empty-text">연장 확인이 필요한 회원권이 없습니다.</td></tr>';
  renderDashboardPager("#rechargePager", rechargeTargets.length, state.rechargePage, "recharge", billingPageSize);

  const serverCancellationLogs = monthBillings
    .map(paymentCancellationAuditLog)
    .filter(Boolean);
  $("#billingLog").innerHTML = [...new Set([...serverCancellationLogs, ...billingLogs])]
    .slice(0, 20)
    .map((item) => `<li>${escapeHtml(item)}</li>`)
    .join("");
}

function paymentActionFor(item, index) {
  const context = (label) => `aria-label="${escapeHtml(`${item.member || "회원"} · ${item.item || "결제"} · ${label}`)}" title="${escapeHtml(`${item.member || "회원"} · ${item.item || "결제"} · ${label}`)}"`;
  if (item.status === "check") return item.providerPaymentId
    ? `<button class="small-button" type="button" data-review-payment="${index}" ${context("서버 확인")}>서버 확인</button>${paymentCancelButtonFor(index, "대기취소")}`
    : '<button class="small-button" type="button" disabled>서버 결제번호 없음</button>';
  if (item.status === "unverified") return `<button class="small-button" type="button" data-review-payment="${index}" ${context("서버 연결 확인")}>서버 연결 확인</button>${paymentCancelButtonFor(index, "대기취소")}`;
  if (item.status === "failed") return `<button class="small-button" type="button" data-failed-payment="${index}" ${context("실패 확인")}>실패 확인</button>${paymentCancelButtonFor(index, "대기취소")}`;
  if (item.status === "draft") return '<button class="small-button" type="button" disabled>회원 결제 대기</button>';
  if (item.status === "server_ready") {
    const label = String(item.method || "") === "bank_transfer"
      ? "입금 확인"
      : isStaleReadyPayment(item) ? "상태 확인" : "결제 확인";
    return `<button class="small-button" type="button" data-server-ready-payment="${index}" ${context(label)}>${label}</button>${paymentCancelButtonFor(index, "대기취소")}`;
  }
  if (item.status === "paid") return `<button class="small-button" type="button" data-paid-payment="${index}" ${context("결제 완료 상세")}>완료됨</button>${paymentFullCancelButtonFor(item, index)}${paymentRefundButtonFor(item, index)}`;
  if (item.status === "refund_manual_pending") return `<button class="small-button danger-action" type="button" data-refund-payment="${index}" ${context("실제 송금 후 환불 완료 확인")}>송금완료 확인</button>`;
  if (item.status === "refund_processing") return `<button class="small-button" type="button" disabled>환불처리중</button>`;
  if (item.status === "cancel_reconcile") return paymentCancelButtonFor(index, "취소 상태 맞추기");
  if (item.status === "refund_reconcile") return `<button class="small-button danger-action" type="button" data-refund-payment="${index}" ${context("환불 동기화 확인")}>동기화 확인</button>`;
  if (item.status === "cancelled") return `<button class="small-button" type="button" disabled>취소완료</button>`;
  if (item.status === "refunded") return `<button class="small-button" type="button" disabled>환불완료</button>`;
  return "";
}

function paymentOwnerHasHistoricalRecord(item = {}) {
  const userId = String(item.serverUserId || "");
  if (!userId) return false;
  return (adminLiveDataState.memberDatabaseRecords || []).some((record) => (
    String(record.user_id || record.userId || "") === userId
    && String(record.record_status || record.recordStatus || "").toLowerCase() === "historical"
    && !String(record.current_ticket_id || record.currentTicketId || "")
  ));
}

function isHistoricalImportedPayment(item = {}) {
  const providerPaymentId = String(item.providerPaymentId || "").toLowerCase();
  const provider = String(item.provider || "").toLowerCase();
  const method = String(item.method || "").toLowerCase();
  const requestedAt = Date.parse(String(item.requestedAt || ""));
  const verifiedAt = Date.parse(String(item.verifiedAt || item.paidAt || ""));
  const historicalMemberEvidence = paymentOwnerHasHistoricalRecord(item);
  const preservedManualEvidence = provider === "admin_manual"
    && (!item.productId || historicalMemberEvidence)
    && Number.isFinite(requestedAt)
    && Number.isFinite(verifiedAt)
    && requestedAt - verifiedAt >= 24 * 60 * 60 * 1000;
  return providerPaymentId.startsWith("sheet_")
    || providerPaymentId.startsWith("legacy_")
    || providerPaymentId.startsWith("import_")
    || provider === "google_sheet_history"
    || method.includes("legacy")
    || method.includes("기존 기록")
    || preservedManualEvidence;
}

function paymentRequiresTicketRepair(item = {}) {
  return item.status === "paid"
    && !item.ticketId
    && !item.oneDayBookingId
    && !isHistoricalImportedPayment(item);
}

function chargeStatusForPayment(item = {}) {
  if (item.status === "refund_manual_pending") return { label: "환불 송금 대기", tone: "warn", detail: "현금 환불이 접수됐습니다. 실제 송금 확인 전까지 이용권 사용과 원데이 예약이 잠시 정지됩니다." };
  if (item.status === "refund_processing") return { label: "환불 처리중", tone: "warn", detail: "PortOne 취소와 내부 회원권 반영이 진행 중입니다." };
  if (item.status === "refund_reconcile") return { label: "동기화 필요", tone: "danger", detail: "PG 취소 결과와 내부 결제·회원권 상태를 다시 맞춰야 합니다." };
  if (item.status === "paid" && item.oneDayBookingId) return { label: "원데이 예약완료", tone: "good", detail: "결제 확인 후 선택한 코치와 시간으로 한 번만 예약됐습니다." };
  if (item.status === "paid" && item.ticketId) return { label: "회원권 충전완료", tone: "good", detail: "결제검증 후 연결 회원권이 활성화됩니다." };
  if (item.status === "paid" && isHistoricalImportedPayment(item)) return { label: "이관 결제 기록", tone: "neutral", detail: "기존 장부에서 보존한 결제 증빙이며 현재 회원권 자동 연결 대상이 아닙니다." };
  if (item.status === "paid") return { label: "회원권 연결 확인", tone: "warn", detail: "결제는 확인됐지만 연결된 회원권 ID가 없습니다." };
  if (isStaleReadyPayment(item)) return { label: "오래된 결제 대기", tone: "warn", detail: "결제창 생성 후 1시간 이상 완료 확인이 없습니다. PortOne 상태 확인 전에는 취소하거나 회원권을 변경하지 않습니다." };
  if (item.status === "server_ready") return { label: "결제 전 대기", tone: "neutral", detail: "회원이 Toss 결제를 완료하면 서버검증 후 자동 충전됩니다." };
  if (item.status === "unverified") return { label: "서버검증 대기", tone: "warn", detail: "결제창 완료 후 서버 검증이 필요합니다." };
  if (item.status === "cancelled") return { label: "취소/환불완료", tone: "neutral", detail: "결제가 취소됐고 연결 회원권은 충전되지 않거나 환불 처리됩니다." };
  if (item.status === "refunded") return { label: "환불완료", tone: "neutral", detail: "환불 완료 항목은 현재 이용권으로 보지 않습니다." };
  if (item.status === "failed") return { label: "충전 중단", tone: "danger", detail: "결제 실패 항목은 회원권을 충전하지 않습니다." };
  return { label: "확인 필요", tone: "warn", detail: "관리자 확인 후 회원권 상태를 맞춰야 합니다." };
}

function renderPaymentChargeAudit() {
  const target = $("#paymentChargeAudit");
  if (!target) return;
  const tracked = billings
    .filter((item) => item.providerPaymentId || item.source === "Supabase 결제")
    .slice(0, 6);
  target.innerHTML = tracked.length
    ? tracked.map((item) => {
        const status = chargeStatusForPayment(item);
        return `
          <article class="payment-charge-card ${status.tone}">
            <div>
              <span>${escapeHtml(item.member)}</span>
              <strong>${escapeHtml(item.item)}</strong>
              <small>${escapeHtml(status.detail)}</small>
              ${item.ticketId ? `<small>회원권 ${escapeHtml(String(item.ticketId).slice(0, 8))}</small>` : ""}
            </div>
            ${badge(status.tone, status.label)}
          </article>`;
      }).join("")
    : "<p class='empty-text'>서버 결제 기록을 불러오면 회원권 충전 상태가 표시됩니다.</p>";
}

async function verifyBillingPaymentItem(item) {
  if (!item?.providerPaymentId) {
    billingLogs.unshift(`${item?.member || "회원"} ${item?.item || "결제"} 서버검증 실패: paymentId 없음`);
    renderAll();
    showToast("paymentId가 없어 서버 검증을 실행할 수 없습니다");
    return;
  }
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.readiness?.().ready) {
    billingLogs.unshift(`${item.member} ${item.item} 서버검증 실패: Supabase 연결값 없음`);
    renderAll();
    showToast("Supabase 연결값 확인 필요");
    return;
  }

  item.statusLabel = "서버검증중";
  billingLogs.unshift(`${item.member} ${item.item} 서버검증 실행: ${item.providerPaymentId}`);
  renderAll();

  try {
    const bankTransfer = String(item.method || "") === "bank_transfer";
    const lateDeposit = bankTransfer && Number.isFinite(Date.parse(item.depositDueAt || "")) && Date.now() > Date.parse(item.depositDueAt);
    const bankPrompt = lateDeposit
      ? `${item.member} 회원의 입금기한이 지났습니다.\n실제 입금 ${money.format(item.finalAmount || item.amount)}원을 직접 확인한 경우에만 승인하세요.`
      : `${item.member} 회원의 ${money.format(item.finalAmount || item.amount)}원 입금을 확인했습니까?\n확인 후에만 회원권 또는 원데이 예약이 생성됩니다.`;
    if (bankTransfer && !window.confirm(bankPrompt)) {
      item.status = "server_ready";
      item.statusLabel = "입금확인대기";
      renderAll();
      return;
    }
    const result = await client.invokeFunction(bankTransfer ? "portone-payment/bank-transfer-confirm" : "portone-payment/verify", {
      body: {
        paymentId: item.providerPaymentId,
        ...(bankTransfer ? {
          confirmedAmount: Number(item.finalAmount || item.amount || 0),
          acceptLateDeposit: lateDeposit,
        } : {}),
      },
    });
    if (result?.ok) {
      item.status = result.status === "verified" || result.status === "already_verified" ? "paid" : "check";
      item.statusLabel = result.chargedTicket ? "검증/충전완료" : "서버검증완료";
      billingLogs.unshift(`${item.member} ${item.item} 서버검증 완료: ${result.status}`);
      await loadServerPaymentsIntoBilling({ silent: true });
      showToast(bankTransfer ? "입금 확인과 회원권 반영이 완료됐습니다" : "서버 결제 검증 완료");
    } else if (result?.code === "payment_not_paid") {
      item.status = "server_ready";
      item.statusLabel = "결제대기";
      billingLogs.unshift(`${item.member} ${item.item} 아직 Toss 결제 완료 전: ${result.portoneStatus || "pending"}`);
      showToast("아직 결제 완료 전입니다");
    } else {
      item.status = "check";
      item.statusLabel = "검증확인필요";
      billingLogs.unshift(`${item.member} ${item.item} 서버검증 확인 필요: ${result?.code || "unknown"}`);
      showToast("서버 검증 확인 필요");
    }
  } catch (error) {
    const code = error?.payload?.code || error?.message || "server_error";
    if (code === "payment_not_paid") {
      item.status = "server_ready";
      item.statusLabel = "결제대기";
      billingLogs.unshift(`${item.member} ${item.item} 아직 Toss 결제 완료 전`);
      showToast("아직 결제 완료 전입니다");
    } else {
      item.status = "check";
      item.statusLabel = "검증실패";
      billingLogs.unshift(`${item.member} ${item.item} 서버검증 실패: ${code}`);
      showToast("서버 검증 실패");
    }
  }
  renderAll();
}

async function ensureAdminPaymentCancelReady(item = {}) {
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.readiness?.().ready) {
    billingLogs.unshift(`${item.member || "회원"} ${item.item || "결제"} 취소 차단: Supabase 연결값 없음`);
    renderAll();
    showToast("Supabase 연결 후 결제취소 가능");
    return false;
  }
  if (!client.getSession?.()?.access_token) {
    billingLogs.unshift(`${item.member || "회원"} ${item.item || "결제"} 취소 차단: 관리자 로그인 필요`);
    renderAll();
    showToast("관리자 로그인 후 결제취소 가능");
    return false;
  }
  if (!adminPaymentCancelReady()) {
    await refreshAdminImportAuthState();
  }
  if (!adminPaymentCancelReady()) {
    billingLogs.unshift(`${item.member || "회원"} ${item.item || "결제"} 취소 차단: 관리자 권한 확인 필요`);
    renderAll();
    showToast("관리자 권한 계정만 결제취소 가능");
    return false;
  }
  return true;
}

function newRefundIdempotencyKey() {
  const value = window.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `refund:${value}`;
}

function refundErrorText(code = "") {
  const labels = {
    login_required: "관리자 로그인이 필요합니다.",
    admin_role_required: "관리자 권한 계정만 환불할 수 있습니다.",
    payment_not_found: "결제 기록을 찾지 못했습니다.",
    payment_not_verified: "서버 검증이 끝난 결제만 환불할 수 있습니다.",
    linked_ticket_not_found: "결제와 연결된 이용권을 찾지 못했습니다.",
    refund_preview_changed: "결제 또는 이용 횟수가 바뀌었습니다. 새 계산값을 확인해 주세요.",
    ticket_usage_changed: "이용 횟수가 바뀌었습니다. 새 계산값을 확인해 주세요.",
    policy_fallback_confirmation_required: "현재 정책 기준 계산 확인이 필요합니다.",
    refund_confirmation_required: "최종 확인란에 환불을 입력해 주세요.",
    refund_reason_required: "환불 사유를 입력해 주세요.",
    refund_in_progress: "같은 결제의 환불이 이미 처리 중입니다.",
    manual_refund_request_failed: "현금 환불 접수를 저장하지 못했습니다. 결제 상태를 다시 확인해 주세요.",
    manual_refund_cancel_confirmation_required: "환불 접수를 취소하려면 최종 확인란에 접수취소를 입력해 주세요.",
    manual_transfer_confirmation_required: "실제 송금 후 최종 확인란에 송금완료를 입력해 주세요.",
    manual_transfer_reference_required: "은행명·끝 4자리 또는 이체확인번호를 입력해 주세요.",
    manual_transfer_reference_contains_account_number: "전체 계좌번호는 저장할 수 없습니다. 끝 4자리만 입력해 주세요.",
    manual_refund_not_awaiting_transfer: "송금 대기 중인 현금 환불이 아닙니다. 결제 상태를 새로고침해 주세요.",
    manual_refund_bank_transfer_only: "현금·계좌이체 결제만 수동 송금 완료 처리할 수 있습니다.",
    reconcile_required: "PG 취소 결과와 내부 기록을 다시 맞춰야 합니다.",
    provider_amount_mismatch: "PG 결제금액과 서버 결제금액이 달라 환불을 중단했습니다.",
    provider_cancel_failed: "PG 환불 요청에 실패했습니다. 결제 상태를 확인해 주세요.",
    bank_transfer_use_refund_flow: "계좌이체는 PG 취소가 아니라 환불 계산에서 처리해 주세요.",
    linked_one_day_booking_not_found: "결제와 연결된 원데이 예약을 찾지 못했습니다.",
    nothing_to_refund: "계산된 환불액이 0원이라 자동 환불할 수 없습니다.",
  };
  return labels[code] || "환불 처리 상태를 확인해 주세요.";
}

function renderRefundModal() {
  const target = $("#refundModalContent");
  const fallback = $("#refundFallbackConfirmation");
  const message = $("#refundFormMessage");
  const confirmButton = $("#confirmRefundButton");
  const reconcileButton = $("#retryRefundReconcile");
  const cancelManualRequestButton = $("#cancelManualRefundRequest");
  const reasonField = $("#refundReasonField");
  const transferReferenceField = $("#refundTransferReferenceField");
  const confirmationInput = $("#refundConfirmationText");
  const item = billings[refundFlowState.itemIndex] || {};
  const manualCashRefund = isManualCashRefundItem(item);
  if (!target) return;
  if (refundFlowState.loading) {
    target.innerHTML = `<div class="refund-loading">결제와 이용권 기록을 확인하고 있습니다.</div>`;
  } else if (!refundFlowState.preview) {
    target.innerHTML = `<div class="refund-loading">${escapeHtml(refundFlowState.message || "환불 계산값을 불러오지 못했습니다.")}</div>`;
  } else {
    const preview = refundFlowState.preview;
    const policySource = preview.policySnapshotSource === "current_policy_fallback" ? "현재 정책 기준" : "구매 당시 정책";
    target.innerHTML = `
      <div class="refund-target-summary">
        <div>
          <strong>${escapeHtml(preview.memberName || "회원")} · ${escapeHtml(preview.productName || "회원권")}</strong>
          <span>총 ${numericValue(preview.totalSessions)}회 중 ${numericValue(preview.usedSessions)}회 사용 · 잔여 ${numericValue(preview.remainingSessions)}회</span>
          <small>결제번호 ${escapeHtml(preview.paymentId || "확인 필요")} · ${escapeHtml(policySource)}</small>
        </div>
        ${badge(preview.requiresPolicyFallbackConfirmation ? "warn" : "good", policySource)}
      </div>
      <div class="refund-amount-grid">
        <div><span>실제 결제금액</span><strong>${money.format(numericValue(preview.paidAmount))}원</strong></div>
        <div><span>할인 전 기준금액</span><strong>${money.format(numericValue(preview.originalAmount, preview.paidAmount))}원</strong></div>
        <div><span>사용 회차 차감</span><strong>-${money.format(numericValue(preview.usedAmount))}원</strong></div>
        <div><span>위약금 ${numericValue(preview.penaltyRate)}%</span><strong>-${money.format(numericValue(preview.penaltyAmount))}원</strong></div>
        ${numericValue(preview.reservationFee) ? `<div><span>첫 수업 월 예약금</span><strong>-${money.format(numericValue(preview.reservationFee))}원</strong></div>` : ""}
        <div class="refund-total"><span>최종 환불액</span><strong>${money.format(numericValue(preview.refundAmount))}원</strong></div>
      </div>
      <p class="refund-policy-line">실납부액 - 할인 전 사용 회차 - 할인 전 원가의 위약금 - 첫 수업 월 예약금 · 환불 완료 시 연결 이용권의 잔여 횟수는 0회가 됩니다.</p>
      ${manualCashRefund ? `<div class="refund-fallback-confirmation"><strong>${refundFlowState.manualTransferPending ? "환불 접수됨" : "현금·계좌이체 환불"}</strong><span>${refundFlowState.manualTransferPending ? "실제 송금을 완료한 뒤에만 송금완료를 확인하세요. 그 전에는 이용권 사용이 잠시 정지되고 원데이 자리는 반환됩니다." : "이 버튼은 돈을 자동 송금하지 않습니다. 접수 즉시 이용권 사용을 잠그고, 직접 송금 후 별도로 완료 확인해야 합니다."}</span></div>` : ""}`;
  }
  if (fallback) {
    fallback.hidden = !refundFlowState.preview?.requiresPolicyFallbackConfirmation;
  }
  if (message) {
    message.textContent = refundFlowState.message || "";
    message.className = `form-message ${refundFlowState.tone === "danger" ? "danger" : refundFlowState.tone === "good" ? "good" : ""}`;
  }
  if (confirmButton) {
    confirmButton.disabled = refundFlowState.loading || refundFlowState.submitting || !refundFlowState.preview || refundFlowState.reconcileRequired || refundFlowState.manualPreviewChanged;
    confirmButton.hidden = refundFlowState.reconcileRequired;
    confirmButton.textContent = refundFlowState.submitting
      ? "처리중"
      : refundFlowState.manualTransferPending
        ? "송금 완료 확인"
        : manualCashRefund
          ? "환불 접수"
          : "환불 확정";
  }
  if (reconcileButton) {
    reconcileButton.hidden = !refundFlowState.reconcileRequired;
    reconcileButton.disabled = refundFlowState.submitting;
  }
  if (cancelManualRequestButton) {
    cancelManualRequestButton.hidden = !refundFlowState.manualTransferPending || refundFlowState.reconcileRequired;
    cancelManualRequestButton.disabled = refundFlowState.submitting;
  }
  if (reasonField) reasonField.hidden = refundFlowState.manualTransferPending;
  if (transferReferenceField) transferReferenceField.hidden = !refundFlowState.manualTransferPending;
  if (confirmationInput) confirmationInput.placeholder = refundFlowState.manualTransferPending ? "송금완료" : "환불";
}

function closeRefundModal() {
  $("#refundModal")?.setAttribute("hidden", "");
  $("#refundForm")?.reset();
  Object.assign(refundFlowState, {
    itemIndex: -1,
    preview: null,
    loading: false,
    submitting: false,
    reconcileRequired: false,
    manualTransferPending: false,
    manualPreviewChanged: false,
    idempotencyKey: "",
    message: "",
    tone: "neutral",
  });
}

async function openRefundModal(item, itemIndex) {
  if (!(await ensureAdminPaymentCancelReady(item))) return;
  if (!item?.providerPaymentId) {
    showToast("서버 결제번호가 필요합니다");
    return;
  }
  Object.assign(refundFlowState, {
    itemIndex,
    preview: null,
    loading: true,
    submitting: false,
    reconcileRequired: item.status === "refund_reconcile",
    manualTransferPending: item.status === "refund_manual_pending",
    manualPreviewChanged: false,
    idempotencyKey: newRefundIdempotencyKey(),
    message: "",
    tone: "neutral",
  });
  $("#refundModal")?.removeAttribute("hidden");
  renderRefundModal();
  try {
    const result = await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-preview", {
      body: { paymentId: item.providerPaymentId },
    });
    if (result?.status === "already_refunded") {
      billingLogs.unshift(`${item.member} 환불은 이미 완료된 결제입니다.`);
      await loadServerPaymentsIntoBilling({ silent: true });
      closeRefundModal();
      showToast("이미 환불 완료된 결제입니다");
      return;
    }
    refundFlowState.preview = result?.preview || null;
    refundFlowState.manualPreviewChanged = refundFlowState.manualTransferPending && result?.previewChanged === true;
    refundFlowState.message = refundFlowState.reconcileRequired
      ? "취소 결과를 확인한 뒤 내부 기록을 다시 맞춰 주세요."
      : refundFlowState.manualPreviewChanged
        ? `접수 후 이용 횟수 또는 환불액이 바뀌었습니다. 송금하지 말고 환불 접수를 취소한 뒤 ${money.format(numericValue(result?.preview?.refundAmount))}원으로 다시 접수하세요.`
      : refundFlowState.manualTransferPending
        ? "실제 송금을 확인한 뒤 관리자 PIN, 송금 확인 메모, 송금완료 문구를 입력하세요."
        : isManualCashRefundItem(item)
          ? "계산값을 확인해 환불을 접수하세요. 이 단계에서는 실제 송금과 이용권 환불이 실행되지 않습니다."
          : "계산값을 확인한 뒤 관리자 PIN과 확인 문구를 입력하세요.";
    if (refundFlowState.manualPreviewChanged) refundFlowState.tone = "danger";
  } catch (error) {
    const code = error?.payload?.code || "refund_preview_failed";
    refundFlowState.message = refundErrorText(code);
    refundFlowState.tone = "danger";
  } finally {
    refundFlowState.loading = false;
    renderRefundModal();
  }
}

async function verifyRefundAdminInputs({
  requireReason = true,
  confirmationPhrase = "환불",
  requireTransferReference = false,
} = {}) {
  const reason = $("#refundReason")?.value.trim() || "";
  const confirmation = $("#refundConfirmationText")?.value.trim() || "";
  const transferReference = $("#refundTransferReference")?.value.trim() || "";
  const pin = $("#refundAdminPin")?.value.trim() || "";
  if (requireReason && reason.length < 2) {
    refundFlowState.message = "환불 사유를 2자 이상 입력해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (confirmation !== confirmationPhrase) {
    refundFlowState.message = `최종 확인란에 ${confirmationPhrase}를 입력해 주세요.`;
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (requireTransferReference && transferReference.length < 2) {
    refundFlowState.message = "송금 확인 메모를 입력해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (requireTransferReference && /\d{8,}/.test(transferReference.replace(/[\s-]/g, ""))) {
    refundFlowState.message = "전체 계좌번호는 저장하지 마세요. 은행명·끝 4자리 또는 짧은 이체확인번호만 입력해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (adminPinNeedsSetup()) {
    refundFlowState.message = "먼저 설정의 보안/잠금에서 관리자 PIN을 설정해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (!(await verifyAdminPin(pin))) {
    refundFlowState.message = "관리자 PIN이 맞지 않습니다.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  if (refundFlowState.preview?.requiresPolicyFallbackConfirmation && !$("#acceptRefundPolicyFallback")?.checked) {
    refundFlowState.message = "현재 정책 기준 계산 확인란을 체크해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return null;
  }
  return { reason, confirmation, transferReference };
}

async function confirmRefundFromModal() {
  const item = billings[refundFlowState.itemIndex];
  const preview = refundFlowState.preview;
  if (!item || !preview || refundFlowState.submitting) return;
  const manualTransferConfirmation = refundFlowState.manualTransferPending;
  const inputs = await verifyRefundAdminInputs({
    requireReason: !manualTransferConfirmation,
    confirmationPhrase: manualTransferConfirmation ? "송금완료" : "환불",
    requireTransferReference: manualTransferConfirmation,
  });
  if (!inputs) return;
  refundFlowState.submitting = true;
  const manualCashRefund = isManualCashRefundItem(item);
  refundFlowState.message = manualTransferConfirmation
    ? "송금 완료 증빙과 내부 이용권 반영을 처리하고 있습니다."
    : manualCashRefund
      ? "현금·계좌이체 환불을 접수하고 이용권 사용을 잠그고 있습니다."
    : "PortOne 환불과 내부 이용권 반영을 처리하고 있습니다.";
  refundFlowState.tone = "neutral";
  renderRefundModal();
  try {
    const result = manualTransferConfirmation
      ? await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-manual-confirm", {
          body: {
            paymentId: item.providerPaymentId,
            expectedRefundAmount: numericValue(preview.refundAmount),
            confirmation: inputs.confirmation,
            transferReference: inputs.transferReference,
          },
        })
      : await window.TennisNoteDataClient.invokeFunction("portone-payment/refund", {
          body: {
            paymentId: item.providerPaymentId,
            expectedRefundAmount: numericValue(preview.refundAmount),
            expectedUsedSessions: numericValue(preview.usedSessions),
            reason: inputs.reason,
            confirmation: inputs.confirmation,
            acceptPolicyFallback: Boolean($("#acceptRefundPolicyFallback")?.checked),
            idempotencyKey: refundFlowState.idempotencyKey,
          },
        });
    if (result?.ok) {
      const manualPending = result.status === "manual_transfer_pending";
      billingLogs.unshift(manualPending
        ? `${item.member} 현금 환불 접수: ${money.format(numericValue(result.refundAmount || preview.refundAmount))}원 · 실제 송금 대기`
        : `${item.member} 환불 완료: ${money.format(numericValue(result.refundAmount || preview.refundAmount))}원`);
      closeRefundModal();
      await loadServerPaymentsIntoBilling({ silent: true });
      showToast(manualPending
        ? "환불 접수됨 · 실제 송금 후 송금완료를 확인하세요"
        : manualCashRefund
          ? "송금 확인과 이용권 환불 반영 완료"
          : "환불과 이용권 반영 완료");
      return;
    }
    if (result?.code === "reconcile_required") {
      refundFlowState.reconcileRequired = true;
      refundFlowState.message = refundErrorText(result.code);
      refundFlowState.tone = "danger";
    } else {
      refundFlowState.message = refundErrorText(result?.code);
      refundFlowState.tone = "danger";
      if (result?.preview) refundFlowState.preview = result.preview;
    }
  } catch (error) {
    const code = error?.payload?.code || "refund_failed";
    if (code === "reconcile_required") refundFlowState.reconcileRequired = true;
    if (error?.payload?.preview) refundFlowState.preview = error.payload.preview;
    refundFlowState.message = refundErrorText(code);
    refundFlowState.tone = "danger";
  } finally {
    refundFlowState.submitting = false;
    renderRefundModal();
  }
}

async function reconcileRefundFromModal() {
  const item = billings[refundFlowState.itemIndex];
  if (!item || refundFlowState.submitting) return;
  const inputs = await verifyRefundAdminInputs({ requireReason: false });
  if (!inputs) return;
  refundFlowState.submitting = true;
  refundFlowState.message = "PG 취소 결과와 내부 기록을 다시 확인하고 있습니다.";
  refundFlowState.tone = "neutral";
  renderRefundModal();
  try {
    const result = await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-reconcile", {
      body: { paymentId: item.providerPaymentId },
    });
    if (result?.ok) {
      billingLogs.unshift(`${item.member} 환불 상태 동기화 완료`);
      closeRefundModal();
      await loadServerPaymentsIntoBilling({ silent: true });
      showToast("환불 상태 동기화 완료");
      return;
    }
    refundFlowState.message = refundErrorText(result?.code);
    refundFlowState.tone = "danger";
  } catch (error) {
    refundFlowState.message = refundErrorText(error?.payload?.code || "reconcile_failed");
    refundFlowState.tone = "danger";
  } finally {
    refundFlowState.submitting = false;
    renderRefundModal();
  }
}

async function cancelManualRefundRequestFromModal() {
  const item = billings[refundFlowState.itemIndex];
  if (!item || !refundFlowState.manualTransferPending || refundFlowState.submitting) return;
  const confirmation = $("#refundConfirmationText")?.value.trim() || "";
  const pin = $("#refundAdminPin")?.value.trim() || "";
  if (confirmation !== "접수취소") {
    refundFlowState.message = "환불 접수를 취소하려면 최종 확인란에 접수취소를 입력해 주세요.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return;
  }
  if (adminPinNeedsSetup() || !(await verifyAdminPin(pin))) {
    refundFlowState.message = adminPinNeedsSetup()
      ? "먼저 설정의 보안/잠금에서 관리자 PIN을 설정해 주세요."
      : "관리자 PIN이 맞지 않습니다.";
    refundFlowState.tone = "danger";
    renderRefundModal();
    return;
  }
  refundFlowState.submitting = true;
  refundFlowState.message = "실제 송금 전 환불 접수를 취소하고 있습니다.";
  refundFlowState.tone = "neutral";
  renderRefundModal();
  try {
    const result = await window.TennisNoteDataClient.invokeFunction("portone-payment/refund-manual-cancel", {
      body: { paymentId: item.providerPaymentId, confirmation },
    });
    if (result?.ok) {
      billingLogs.unshift(`${item.member} 현금 환불 접수 취소 · 결제와 이용권 유지`);
      closeRefundModal();
      await loadServerPaymentsIntoBilling({ silent: true });
      showToast("환불 접수 취소됨 · 결제와 이용권은 유지됩니다");
      return;
    }
    refundFlowState.message = refundErrorText(result?.code);
    refundFlowState.tone = "danger";
  } catch (error) {
    refundFlowState.message = refundErrorText(error?.payload?.code || "manual_refund_cancel_failed");
    refundFlowState.tone = "danger";
  } finally {
    refundFlowState.submitting = false;
    renderRefundModal();
  }
}

function paymentCancelConfirmationPhrase(item = {}) {
  return ["paid", "cancel_reconcile"].includes(item.status) ? "전액취소" : "대기취소";
}

function newPaymentCancelIdempotencyKey() {
  const value = window.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `cancel:${value}`;
}

function renderPaymentCancelModal() {
  const item = billings[paymentCancelFlowState.itemIndex];
  const target = $("#paymentCancelModalContent");
  const message = $("#paymentCancelFormMessage");
  const submitButton = $("#confirmPaymentCancelButton");
  const help = $("#paymentCancelConfirmationHelp");
  const title = $("#paymentCancelModalTitle");
  if (!target || !item) return;
  const isPaid = ["paid", "cancel_reconcile"].includes(item.status);
  const amount = paymentFullCancelAmount(item);
  const phrase = paymentCancelConfirmationPhrase(item);
  if (title) title.textContent = isPaid ? "PG 전액 결제취소" : "결제 대기건 취소";
  target.innerHTML = `
    <div class="refund-target-summary">
      <div>
        <strong>${escapeHtml(item.member || "회원")} · ${escapeHtml(item.item || "결제")}</strong>
        <span>${escapeHtml(paymentMethodLabel(item.method))} · ${escapeHtml(item.statusLabel || item.status || "상태 확인")}</span>
        <small>취소 대상 금액 ${money.format(amount)}원</small>
      </div>
      ${badge(isPaid ? "danger" : "warn", isPaid ? "실제 PG 승인" : "결제 전 대기")}
    </div>
    <p class="payment-cancel-warning">${isPaid ? "일반 환불 계산과 별도로 PG 승인금액 전체를 취소하고 연결 회원권을 비활성화합니다." : "결제가 완료되지 않은 대기 기록을 취소합니다. 실제 결제 여부가 불명확하면 먼저 상태 확인을 실행하세요."}</p>`;
  if (help) help.textContent = `${isPaid ? "실제 PG 승인 전체를 취소" : "결제 대기 기록을 취소"}하려면 ${phrase}를 입력하세요.`;
  if ($("#paymentCancelConfirmationText")) $("#paymentCancelConfirmationText").placeholder = phrase;
  if (message) {
    message.textContent = paymentCancelFlowState.message || "";
    message.className = `form-message ${paymentCancelFlowState.tone === "danger" ? "danger" : paymentCancelFlowState.tone === "good" ? "good" : ""}`;
  }
  if (submitButton) {
    submitButton.disabled = paymentCancelFlowState.submitting;
    submitButton.textContent = paymentCancelFlowState.submitting ? "취소 처리 중" : `${phrase} 실행`;
  }
  [$("#closePaymentCancelModal"), $("#dismissPaymentCancelModal")].forEach((button) => {
    if (button) button.disabled = paymentCancelFlowState.submitting;
  });
}

function closePaymentCancelModal() {
  if (paymentCancelFlowState.submitting) return;
  $("#paymentCancelModal")?.setAttribute("hidden", "");
  $("#paymentCancelForm")?.reset();
  Object.assign(paymentCancelFlowState, {
    itemIndex: -1,
    submitting: false,
    idempotencyKey: "",
    message: "",
    tone: "neutral",
  });
}

async function openPaymentCancelModal(item, itemIndex = billings.indexOf(item)) {
  const serverBacked = Boolean(item?.serverPaymentId);
  const localPending = item && ["check", "unverified", "failed"].includes(item.status) && !serverBacked;
  if (!item?.providerPaymentId) {
    billingLogs.unshift(`${item?.member || "회원"} ${item?.item || "결제"} 취소 실패: paymentId 없음`);
    renderAll();
    showToast("paymentId가 없어 결제취소를 실행할 수 없습니다");
    return;
  }
  if (!localPending && !["paid", "server_ready", "failed", "cancel_reconcile"].includes(item.status)) {
    showToast("취소 가능한 상태가 아닙니다");
    return;
  }
  if (!(await ensureAdminPaymentCancelReady(item))) return;
  Object.assign(paymentCancelFlowState, {
    itemIndex,
    submitting: false,
    idempotencyKey: newPaymentCancelIdempotencyKey(),
    message: "대상과 금액을 확인하고 취소 사유와 최종 확인 문구를 입력하세요.",
    tone: "neutral",
  });
  $("#paymentCancelForm")?.reset();
  if (!item || !["paid", "cancel_reconcile"].includes(item.status)) {
    if ($("#paymentCancelReason")) $("#paymentCancelReason").value = "결제 전 대기건 정리";
  }
  $("#paymentCancelModal")?.removeAttribute("hidden");
  renderPaymentCancelModal();
  $("#paymentCancelReason")?.focus();
}

async function confirmPaymentCancelFromModal() {
  const item = billings[paymentCancelFlowState.itemIndex];
  if (!item || paymentCancelFlowState.submitting) return;
  const reason = $("#paymentCancelReason")?.value.trim() || "";
  const confirmation = $("#paymentCancelConfirmationText")?.value.trim() || "";
  const expectedConfirmation = paymentCancelConfirmationPhrase(item);
  if (reason.length < 2) {
    paymentCancelFlowState.message = "결제취소 사유를 2자 이상 입력해 주세요.";
    paymentCancelFlowState.tone = "danger";
    renderPaymentCancelModal();
    return;
  }
  if (confirmation !== expectedConfirmation) {
    paymentCancelFlowState.message = `최종 확인란에 ${expectedConfirmation}를 입력해 주세요.`;
    paymentCancelFlowState.tone = "danger";
    renderPaymentCancelModal();
    return;
  }
  await executeBillingPaymentCancellation(item, reason);
}

async function executeBillingPaymentCancellation(item, reason) {
  const serverBacked = Boolean(item?.serverPaymentId);
  const localPending = item && ["check", "unverified", "failed"].includes(item.status) && !serverBacked;
  const actionLabel = ["paid", "cancel_reconcile"].includes(item.status) ? "실제 결제취소" : "결제 전 대기취소";
  const cancelAmount = paymentFullCancelAmount(item);
  if (paymentCancelInFlight.has(item.providerPaymentId)) {
    paymentCancelFlowState.message = "같은 결제의 취소 요청이 이미 처리 중입니다.";
    paymentCancelFlowState.tone = "danger";
    renderPaymentCancelModal();
    return;
  }
  if (localPending) {
    item.status = "cancelled";
    item.statusLabel = "대기취소";
    item.refundReason = reason;
    item.refundedAt = new Date().toISOString();
    billingLogs.unshift(`${item.member} ${item.item} 대기건 정리: ${reason}`);
    saveSnapshot();
    closePaymentCancelModal();
    renderAll();
    showToast("결제 대기건 정리 완료");
    return;
  }
  const client = window.TennisNoteDataClient;
  if (!client?.invokeFunction || !client.readiness?.().ready) {
    billingLogs.unshift(`${item.member} ${item.item} 취소 실패: Supabase 연결값 없음`);
    paymentCancelFlowState.message = "Supabase 연결값을 확인해 주세요.";
    paymentCancelFlowState.tone = "danger";
    renderPaymentCancelModal();
    return;
  }

  paymentCancelFlowState.submitting = true;
  paymentCancelFlowState.message = "PortOne 결제취소와 연결 회원권 비활성화를 처리하고 있습니다.";
  paymentCancelFlowState.tone = "neutral";
  item.statusLabel = "취소처리중";
  billingLogs.unshift(`${item.member} ${item.item} ${actionLabel} 요청`);
  paymentCancelInFlight.add(item.providerPaymentId);
  renderPaymentCancelModal();
  renderAll();

  try {
    const result = await client.invokeFunction("portone-payment/cancel", {
      body: {
        paymentId: item.providerPaymentId,
        amount: cancelAmount,
        reason,
        idempotencyKey: paymentCancelFlowState.idempotencyKey,
      },
    });
    if (result?.ok) {
      item.status = "cancelled";
      item.statusLabel = result.localOnly ? "대기취소" : "결제취소";
      const alreadyCancelled = result?.status === "already_cancelled";
      billingLogs.unshift(`${item.member} ${item.item} 취소 완료: ${alreadyCancelled ? "이미 취소된 결제" : result.localOnly ? "대기건 정리" : "PortOne 취소"}`);
      await loadServerPaymentsIntoBilling({ silent: true, force: true });
      paymentCancelFlowState.submitting = false;
      closePaymentCancelModal();
      showToast(alreadyCancelled ? "이미 취소 완료된 결제입니다" : result.localOnly ? "대기 결제 정리 완료" : "결제 취소 완료");
    } else {
      item.statusLabel = "취소확인필요";
      billingLogs.unshift(`${item.member} ${item.item} 취소 확인 필요: ${result?.code || "unknown"}`);
      paymentCancelFlowState.message = refundErrorText(result?.code || "provider_cancel_failed");
      paymentCancelFlowState.tone = "danger";
    }
  } catch (error) {
    const code = error?.payload?.code || error?.message || "server_error";
    item.statusLabel = "취소실패";
    billingLogs.unshift(`${item.member} ${item.item} 취소 실패: ${code}`);
    paymentCancelFlowState.message = refundErrorText(code);
    paymentCancelFlowState.tone = "danger";
  } finally {
    paymentCancelInFlight.delete(item.providerPaymentId);
    paymentCancelFlowState.submitting = false;
  }
  renderPaymentCancelModal();
  renderAll();
}

async function cancelBillingPaymentItem(item, itemIndex = billings.indexOf(item)) {
  await openPaymentCancelModal(item, itemIndex);
}

function recordStatusBadge(record) {
  if (record.priority === "urgent") return badge("danger", record.statusLabel || "긴급");
  const statusTone = {
    pending: "pending",
    feedback: "requested",
    done: "confirmed",
    issue: "attention",
  };
  return badge(statusTone[record.group] || "neutral", record.statusLabel);
}

function buildAdminRecordContext() {
  const ticketCoachByMember = new Map();
  [...tickets, ...expiredTickets].forEach((ticket) => {
    String(ticket.member || "").split("&").map((name) => name.trim()).filter(Boolean).forEach((name) => {
      if (!ticketCoachByMember.has(name) && ticket.coachId) ticketCoachByMember.set(name, ticket.coachId);
    });
  });
  const memberCoachByName = new Map(members.map((member) => [member.name, member.coachId || ""]));
  const userNameById = new Map((adminLiveDataState.users || []).map((user) => [String(user.id), user.name]));
  const mediaCountByJournalId = new Map();
  (adminLiveDataState.mediaFiles || []).forEach((media) => {
    const key = String(media.journal_entry_id || "");
    if (!key) return;
    mediaCountByJournalId.set(key, (mediaCountByJournalId.get(key) || 0) + 1);
  });
  const lessonRecordByLessonId = new Map(
    (adminLiveDataState.lessonRecords || [])
      .filter((record) => record.lesson_id)
      .map((record) => [String(record.lesson_id), record]),
  );
  const lessonById = new Map();
  lessons.forEach((lesson) => {
    if (lesson.id) lessonById.set(String(lesson.id), lesson);
    if (lesson.serverLessonId) lessonById.set(String(lesson.serverLessonId), lesson);
  });
  const curriculumById = new Map(
    (adminLiveDataState.curriculumRefs || [])
      .filter((curriculum) => curriculum.id)
      .map((curriculum) => [String(curriculum.id), curriculum]),
  );
  const participantRecordsByLessonId = new Map();
  (adminLiveDataState.participantRecords || []).forEach((record) => {
    const lessonId = String(record.lesson_id || "");
    if (!lessonId) return;
    const rows = participantRecordsByLessonId.get(lessonId) || [];
    rows.push(record);
    participantRecordsByLessonId.set(lessonId, rows);
  });
  return {
    ticketCoachByMember,
    memberCoachByName,
    userNameById,
    mediaCountByJournalId,
    lessonRecordByLessonId,
    lessonById,
    curriculumById,
    participantRecordsByLessonId,
  };
}

function recordCoachId(source = {}, context = null) {
  if (source.coachId) return source.coachId;
  const memberNames = String(source.member || "").split("&").map((name) => name.trim()).filter(Boolean);
  if (!memberNames.length) return "";
  if (context) {
    for (const name of memberNames) {
      const ticketCoachId = context.ticketCoachByMember.get(name);
      if (ticketCoachId) return ticketCoachId;
    }
    for (const name of memberNames) {
      const memberCoachId = context.memberCoachByName.get(name);
      if (memberCoachId) return memberCoachId;
    }
    return "";
  }
  const memberTicket = [...tickets, ...expiredTickets].find((ticket) => (
    String(ticket.member || "").split("&").some((name) => memberNames.includes(name.trim()))
  ));
  if (memberTicket?.coachId) return memberTicket.coachId;
  return members.find((member) => memberNames.includes(member.name))?.coachId || "";
}

function withRecordCoach(record, source = record, context = null) {
  const coachId = recordCoachId(source, context);
  return {
    ...record,
    coachId,
    coachName: coachId ? getCoachName(coachId) : "미배정",
  };
}

function pendingRecordType(record = {}) {
  if (record.pendingType) return record.pendingType;
  if (record.actionView === "billing" || record.source === "결제 오류") return "payment";
  if (record.actionView === "schedule" || String(record.source || "").includes("보강")) return "makeup";
  if (String(record.source || "").includes("피드")) return "feedback";
  return "lesson";
}

function legacyNoteRecord(note) {
  const done = note.status === "confirmed";
  return {
    id: `legacy-note-${note.id}`,
    group: done ? "done" : "feedback",
    source: "관리자 샘플",
    member: note.member,
    title: note.lesson,
    detail: note.reflection,
    subDetail: note.next,
    statusLabel: done ? "차감 확인됨" : "작성 필요",
    actionLabel: done ? "완료" : "피드백 작성",
    lessonId: note.serverLessonId || "",
    actionable: !done && Boolean(note.serverLessonId),
  };
}

function recordTimestamp(value) {
  const parsed = Date.parse(value || "");
  return Number.isFinite(parsed) ? parsed : 0;
}

function lessonEndTimestamp(lesson) {
  if (!lesson?.lessonDate || !lesson?.time) return 0;
  const start = new Date(`${lesson.lessonDate}T${lesson.time}:00`);
  if (Number.isNaN(start.getTime())) return 0;
  return start.getTime() + (Number(lesson.durationMinutes) || 20) * 60 * 1000;
}

function sortAdminRecords(records = []) {
  const priorityScore = { urgent: 3, high: 2, normal: 1 };
  return [...records].sort((left, right) => {
    const priorityDifference = (priorityScore[right.priority] || 0) - (priorityScore[left.priority] || 0);
    if (priorityDifference) return priorityDifference;
    return recordTimestamp(right.sortAt) - recordTimestamp(left.sortAt);
  });
}

function pendingLessonRecord(lesson, participant = null) {
  const endedAt = lessonEndTimestamp(lesson);
  const writingDelayed = endedAt > 0 && Date.now() - endedAt > 24 * 60 * 60 * 1000;
  return {
    id: `pending-lesson-${lesson.serverLessonId}-${participant?.userId || "all"}`,
    group: "feedback",
    source: "피드백 미작성",
    member: participant?.name || lesson.member || "회원 확인 필요",
    title: `${lesson.lessonDate || "수업일"} ${lesson.time || ""} · ${getCoachName(lesson.coachId)}`.trim(),
    detail: `${lesson.type || "수업"} ${lesson.durationMinutes || 20}분 · ${writingDelayed ? "수업 종료 후 24시간 초과" : "정상 작성 대기"}`,
    subDetail: "최종 저장 전까지 회원권 차감은 실행되지 않습니다.",
    statusLabel: writingDelayed ? "작성 지연" : "작성 필요",
    actionLabel: "피드백 작성",
    lessonId: lesson.serverLessonId,
    actionable: true,
    priority: writingDelayed ? "high" : "normal",
    urgentReason: "",
    sortAt: endedAt ? new Date(endedAt).toISOString() : `${lesson.lessonDate || ""}T${lesson.time || "00:00"}:00`,
  };
}

function journalBodySummary(body = "") {
  const text = String(body || "").trim();
  if (!text) return "작성 내용 없음";
  try {
    const parsed = JSON.parse(text);
    return parsed.content || parsed.selfMemo || parsed.memo || text;
  } catch {
    return text;
  }
}

function memberJournalRecord(entry, context = null) {
  const memberName = context?.userNameById.get(String(entry.user_id || ""));
  const member = memberName ? { name: memberName } : (adminLiveDataState.users || []).find((user) => user.id === entry.user_id);
  const mediaCount = context
    ? context.mediaCountByJournalId.get(String(entry.id || "")) || 0
    : (adminLiveDataState.mediaFiles || []).filter((media) => media.journal_entry_id === entry.id).length;
  const linkedRecord = context
    ? context.lessonRecordByLessonId.get(String(entry.lesson_id || ""))
      || (context.participantRecordsByLessonId.get(String(entry.lesson_id || "")) || [])
        .find((record) => record.record_status === "final")
    : (adminLiveDataState.lessonRecords || []).find((record) => record.lesson_id === entry.lesson_id);
  const entryLabel = entry.entry_type === "lesson" ? "레슨" : "개인운동";
  return {
    id: `journal-${entry.id}`,
    group: "feedback",
    source: "회원 피드",
    member: member?.name || "회원 확인 필요",
    title: `${entry.entry_date || "날짜 미정"} ${entryLabel}`,
    detail: journalBodySummary(entry.body),
    subDetail: `${mediaCount ? `사진·영상 ${mediaCount}개` : "첨부 없음"}${linkedRecord ? " · 코치 기록 완료" : ""}`,
    statusLabel: linkedRecord ? "피드 확인됨" : "새 피드",
    actionLabel: mediaCount ? "첨부 보기" : "확인",
    journalId: entry.id,
    mediaCount,
    priority: "normal",
    sortAt: entry.updated_at || entry.created_at || `${entry.entry_date || ""}T00:00:00`,
  };
}

function participantOutcomeLabel(outcome = "completed") {
  return ({
    completed: "수업 완료",
    no_show: "노쇼",
    absence: "불참",
    cancelled: "취소",
    holiday: "휴무",
  })[outcome] || "수업 처리";
}

function participantLessonRecord(record, context) {
  const lessonId = String(record.lesson_id || "");
  const lesson = context.lessonById.get(lessonId) || null;
  const memberName = context.userNameById.get(String(record.user_id || "")) || "회원 확인 필요";
  const curriculum = context.curriculumById.get(String(record.next_curriculum_ref_id || "")) || null;
  const recordStatus = String(record.record_status || "draft");
  const isDraft = recordStatus !== "final";
  const deductedSessions = Math.max(0, Number(record.deducted_sessions) || 0);
  const deductionRequested = Boolean(record.deduction_requested);
  const deductionOutcome = ["completed", "no_show", "absence"].includes(String(record.outcome || ""));
  const missingDeduction = !isDraft
    && deductionRequested
    && deductedSessions === 0
    && deductionOutcome;
  const missingTicket = !isDraft && deductionRequested && deductionOutcome && !record.ticket_id;
  const finalizedLessonWithDraft = isDraft && ["completed", "no_show"].includes(String(lesson?.serverStatus || ""));
  const actualIssue = missingDeduction || missingTicket || finalizedLessonWithDraft;
  const outcomeLabel = participantOutcomeLabel(record.outcome);
  const completedLabel = deductedSessions > 0
    ? `완료 · ${deductedSessions}회 차감`
    : "완료 · 차감 없음";
  const detailParts = [
    String(record.coach_comment || "").trim() || (isDraft ? "작성 중인 피드백이 있습니다." : `${outcomeLabel} 기록`),
    curriculum?.title ? `다음 커리큘럼: ${curriculum.title}` : "",
  ].filter(Boolean);
  const lessonDate = lesson?.lessonDate || String(record.finalized_at || record.updated_at || "").slice(0, 10) || "날짜 미정";
  const lessonTime = lesson?.time || "";
  return {
    id: `participant-record-${record.id}`,
    group: actualIssue ? "issue" : isDraft ? "feedback" : "done",
    source: "수업 피드백",
    branchId: lesson?.branchId || "",
    member: memberName,
    title: `${lessonDate} ${lessonTime} · ${outcomeLabel}`.replace(/\s+/g, " ").trim(),
    detail: detailParts.join(" · "),
    subDetail: finalizedLessonWithDraft
      ? "수업 상태는 완료지만 참여자 기록은 아직 초안입니다. 최종 저장 여부를 확인해 주세요."
      : missingTicket
        ? "차감 요청은 있지만 연결된 회원권이 없습니다. 회원권 연결을 확인해 주세요."
        : isDraft
      ? "피드백만 임시 저장됨 · 회원권 차감 안 됨"
      : missingDeduction
        ? "차감 요청과 실제 차감 결과가 다릅니다. 수업 상세에서 확인해 주세요."
        : completedLabel,
    statusLabel: finalizedLessonWithDraft
      ? "완료 상태·초안"
      : missingTicket
        ? "회원권 연결 확인"
        : isDraft
          ? "초안 · 미차감"
          : missingDeduction
            ? "차감 확인 필요"
            : completedLabel,
    actionLabel: actualIssue ? "기록 확인" : isDraft ? "이어 작성" : "처리 완료",
    lessonId,
    serverLessonId: lessonId,
    ticketId: record.ticket_id || "",
    coachId: lesson?.coachId || "",
    coachRoleId: record.coach_role_id || lesson?.coachRoleId || "",
    actionable: Boolean(lesson && (isDraft || actualIssue)),
    priority: actualIssue ? "urgent" : isDraft ? "high" : "normal",
    urgentReason: finalizedLessonWithDraft
      ? "수업 상태와 참여자 기록 상태가 일치하지 않습니다."
      : missingTicket
        ? "최종 차감 기록에 회원권 연결이 없습니다."
        : missingDeduction
          ? "완료 기록은 있지만 요청된 회원권 차감 결과가 0회입니다."
          : "",
    sortAt: record.finalized_at || record.updated_at || record.created_at || lesson?.lessonDate || "",
  };
}

function lessonParticipantTargets(lesson, context) {
  const participantUserIds = Array.isArray(lesson.serverParticipantUserIds)
    ? lesson.serverParticipantUserIds.map(String).filter(Boolean)
    : [];
  if (!participantUserIds.length) return [];
  return participantUserIds.map((userId) => ({
    userId,
    name: context?.userNameById.get(userId) || lesson.member || "회원 확인 필요",
  }));
}

function pendingLessonRecords(context) {
  const completedLessonIds = new Set((adminLiveDataState.lessonRecords || []).map((record) => record.lesson_id));
  const participantRecordsByLessonId = context?.participantRecordsByLessonId || new Map();
  const now = Date.now();
  const ownRoleIds = currentOperationsCoachRoleIds();
  return lessons
    .filter((lesson) => {
      const endedAt = lessonEndTimestamp(lesson);
      return (
        lesson.serverLessonId
        && !lesson.oneDayBooking
        && lesson.serverStatus === "scheduled"
        && endedAt > 0
        && endedAt <= now
        && !completedLessonIds.has(lesson.serverLessonId)
        && (operationsRole() === "admin" || ownRoleIds.has(lesson.coachRoleId))
      );
    })
    .flatMap((lesson) => {
      const lessonRecords = participantRecordsByLessonId.get(String(lesson.serverLessonId)) || [];
      const targets = lessonParticipantTargets(lesson, context);
      if (!targets.length) return lessonRecords.length ? [] : [pendingLessonRecord(lesson)];
      return targets
        .filter((target) => !lessonRecords.some((record) => String(record.user_id || "") === target.userId))
        .map((target) => pendingLessonRecord(lesson, target));
    });
}

function completedLessonRecordIssues(context) {
  const legacyLessonIds = new Set((adminLiveDataState.lessonRecords || []).map((record) => String(record.lesson_id || "")));
  const participantRecordsByLessonId = context?.participantRecordsByLessonId || new Map();
  const ownRoleIds = currentOperationsCoachRoleIds();
  return lessons
    .filter((lesson) => (
      lesson.serverLessonId
      && !lesson.oneDayBooking
      && ["completed", "no_show"].includes(String(lesson.serverStatus || ""))
      && !legacyLessonIds.has(String(lesson.serverLessonId))
      && (operationsRole() === "admin" || ownRoleIds.has(lesson.coachRoleId))
    ))
    .flatMap((lesson) => {
      const lessonRecords = participantRecordsByLessonId.get(String(lesson.serverLessonId)) || [];
      const targets = lessonParticipantTargets(lesson, context);
      const missingTargets = targets.length
        ? targets.filter((target) => !lessonRecords.some((record) => String(record.user_id || "") === target.userId))
        : lessonRecords.length ? [] : [{ userId: "", name: lesson.member || "회원 확인 필요" }];
      return missingTargets.map((target) => ({
        id: `completed-record-missing-${lesson.serverLessonId}-${target.userId || "all"}`,
        group: "issue",
        source: "수업 기록 오류",
        branchId: lesson.branchId || "",
        member: target.name,
        title: `${lesson.lessonDate || "수업일"} ${lesson.time || ""} · ${getCoachName(lesson.coachId)}`.trim(),
        detail: `${lesson.type || "수업"} ${lesson.durationMinutes || 20}분 · 수업 상태 ${lesson.serverStatus === "no_show" ? "노쇼" : "완료"}`,
        subDetail: "해당 참여자의 최종 수업 기록이 없습니다. 수업 상세에서 기록 상태를 확인해 주세요.",
        statusLabel: "완료 기록 누락",
        actionLabel: "기록 확인",
        lessonId: lesson.serverLessonId,
        serverLessonId: lesson.serverLessonId,
        coachId: lesson.coachId || "",
        coachRoleId: lesson.coachRoleId || "",
        actionable: true,
        priority: "urgent",
        urgentReason: "수업 완료 상태와 참여자 최종 기록이 일치하지 않습니다.",
        sortAt: `${lesson.lessonDate || ""}T${lesson.time || "00:00"}:00`,
      }));
    });
}

function lessonLogRecord(log) {
  const done = log.status === "confirmed";
  const hasIssue = done && (!log.coachComment || !(log.nextCurriculumId || log.curriculumId || log.curriculum?.id));
  return {
    id: log.id || `lesson-log-${log.member}-${log.submittedAt || Date.now()}`,
    group: hasIssue ? "issue" : done ? "done" : "feedback",
    source: "회원/코치 기록",
    member: log.member || "회원",
    title: log.lessonLabel || log.lesson || `${log.date || ""} 수업`,
    detail: log.content || log.selfMemo || "회원 운동일지 또는 코치 완료 처리 확인",
    subDetail: log.coachComment ? `코치 코멘트: ${log.coachComment}` : "코치 코멘트 미등록",
    statusLabel: hasIssue ? "기록 보완 필요" : done ? "차감 완료" : "작성 필요",
    actionLabel: hasIssue ? "관리자 확인" : done ? "완료" : "코치앱 작성",
    priority: hasIssue ? "urgent" : !done ? "high" : "normal",
    urgentReason: hasIssue ? "코멘트 또는 다음 커리큘럼 누락을 확인해야 합니다." : "",
    sortAt: log.completedAt || log.submittedAt || log.updatedAt || log.date || "",
  };
}

function feedbackRecord(request) {
  const done = request.status === "코치 답변 완료";
  return {
    id: request.id || `feedback-${request.member}-${request.date || Date.now()}`,
    group: done ? "done" : "feedback",
    source: "운동노트 피드백",
    member: request.member || "회원",
    title: `${request.date || "날짜 미정"} 사진/영상 피드백`,
    detail: request.question || request.memo || "코치 코멘트 요청",
    subDetail: request.coachFeedback ? `답변: ${request.coachFeedback}` : "코치 답변 대기",
    statusLabel: done ? "답변 완료" : "피드백 대기",
    actionLabel: done ? "완료" : "코치앱 답변",
    priority: done ? "normal" : "high",
    sortAt: request.updatedAt || request.createdAt || request.date || "",
  };
}

function urgentOperationsRecords() {
  const paymentRecords = billings
    .filter(paymentRequiresTicketRepair)
    .map((item) => ({
      id: `urgent-payment-${item.serverPaymentId || item.providerPaymentId || item.member}`,
      group: "pending",
      source: "결제 오류",
      member: item.member || "회원 확인 필요",
      title: `${item.item || "회원권 결제"} 연결 누락`,
      detail: `${money.format(Number(item.amount) || 0)}원 결제 후 회원권이 발급되지 않았습니다.`,
      subDetail: "결제 확인 후 회원권 연결이 필요합니다.",
      statusLabel: "긴급",
      actionLabel: "결제 확인",
      actionView: "billing",
      priority: "urgent",
      urgentReason: "결제 완료와 회원권 데이터가 일치하지 않습니다.",
      sortAt: item.verifiedAt || item.paidAt || item.requestedAt || "",
    }));
  const makeupRecords = makeupRequests
    .filter((item) => ["coach_required", "requested", "pending"].includes(item.status))
    .map((item) => ({
      id: `urgent-makeup-${item.id}`,
      group: "pending",
      source: "긴급 보강·변경",
      member: item.member || "회원 확인 필요",
      title: `${item.original || item.absence || "기존 수업"} 변경 요청`,
      detail: `${item.requested || item.makeup || "변경 시간 확인 필요"} · ${item.reason || "사유 미입력"}`,
      subDetail: item.policy || item.statusLabel || "승인 여부 확인 필요",
      statusLabel: "긴급",
      actionLabel: "시간표 확인",
      actionView: "schedule",
      priority: "urgent",
      urgentReason: item.status === "coach_required" || item.status === "pending"
        ? "승인 전 원래 수업을 유지하는 변경 요청입니다."
        : "접수된 보강·변경 요청을 확인해야 합니다.",
      sortAt: item.createdAt || item.requestedAt || item.requested || "",
    }));
  return paymentRecords.concat(makeupRecords);
}

function ticketReviewState(ticket) {
  return window.TennisNoteTicketState?.derive(ticket) || ticket?.status || "unknown";
}

function ticketReviewMember(userId) {
  const normalizedUserId = String(userId || "");
  if (!normalizedUserId) return null;
  return operationBranchMembers().find((member) => (
    memberServerUserIds(member).some((memberUserId) => String(memberUserId) === normalizedUserId)
  )) || null;
}

function ticketReviewLinkContext() {
  const activeLinks = (adminLiveDataState.groupTicketLinks || []).filter((link) => (
    ["active", "linked"].includes(String(link.status || "active").toLowerCase())
    && link.group_account_id
  ));
  const byAccount = new Map();
  const accountIdsByTicket = new Map();
  activeLinks.forEach((link) => {
    const accountId = String(link.group_account_id);
    const account = byAccount.get(accountId) || { userIds: new Set(), ticketIds: new Set() };
    if (link.user_id) account.userIds.add(String(link.user_id));
    if (link.ticket_id) {
      const ticketId = String(link.ticket_id);
      account.ticketIds.add(ticketId);
      const accountIds = accountIdsByTicket.get(ticketId) || new Set();
      accountIds.add(accountId);
      accountIdsByTicket.set(ticketId, accountIds);
    }
    byAccount.set(accountId, account);
  });
  return { byAccount, accountIdsByTicket };
}

function isExpectedPersonalGroupTicketSet(ticketIds, linkContext) {
  if (ticketIds.length < 2) return false;
  let sharedAccountIds = null;
  ticketIds.forEach((ticketId) => {
    const accountIds = linkContext.accountIdsByTicket.get(String(ticketId)) || new Set();
    sharedAccountIds = sharedAccountIds === null
      ? new Set(accountIds)
      : new Set([...sharedAccountIds].filter((accountId) => accountIds.has(accountId)));
  });
  return [...(sharedAccountIds || [])].some((accountId) => {
    const account = linkContext.byAccount.get(accountId);
    return account?.userIds.size >= 2 && account?.ticketIds.size >= 2;
  });
}

function ticketIntegrityReviewRecords() {
  if (operationsRole() !== "admin" || !state.liveScheduleLoaded) return [];
  const relevantStates = new Set(["current", "upcoming", "paused", "pending_payment"]);
  const linkContext = ticketReviewLinkContext();
  const records = [];

  operationBranchMembers().forEach((member) => {
    const ticketsByFingerprint = new Map();
    memberManagementTickets(member)
      .filter((ticket) => relevantStates.has(ticketReviewState(ticket)))
      .forEach((ticket) => {
        const fingerprint = memberTicketDuplicateFingerprint(ticket);
        if (!fingerprint) return;
        const grouped = ticketsByFingerprint.get(fingerprint) || [];
        grouped.push(ticket);
        ticketsByFingerprint.set(fingerprint, grouped);
      });
    [...ticketsByFingerprint.values()].forEach((grouped, index) => {
      if (grouped.length < 2) return;
      const ticketIds = grouped.map((ticket) => String(ticket.serverTicketId || "")).filter(Boolean);
      if (isExpectedPersonalGroupTicketSet(ticketIds, linkContext)) return;
      const ticket = grouped[0];
      const period = [ticket.actualLessonStart || ticket.purchased, ticket.expires].filter(Boolean).join("~");
      records.push({
        id: `ticket-overlap-${member.id}-${index}`,
        group: "issue",
        source: "회원권 점검",
        member: member.name || "회원 확인 필요",
        title: "회원권 중복 가능",
        detail: `${getTicketDisplayProduct(ticket) || ticket.product || "회원권"} · ${getCoachName(ticket.coachId)}`,
        subDetail: `${period || "기간 확인 필요"} · 자동 삭제하지 않았습니다. 두 회원권을 비교해 주세요.`,
        statusLabel: "확인 필요",
        actionLabel: "회원권 확인",
        memberId: member.id,
        ticketId: ticket.serverTicketId || "",
        priority: "urgent",
        urgentReason: "상품·코치·수업 유형·기간·참여자가 같은 회원권이 둘 이상입니다.",
        sortAt: ticket.serverUpdatedAt || ticket.expires || "",
      });
    });
  });

  linkContext.byAccount.forEach((account, accountId) => {
    if (account.userIds.size >= 2 && account.ticketIds.size >= 1) return;
    const accountRow = (adminLiveDataState.groupAccounts || []).find((item) => String(item.id || "") === accountId);
    const firstUserId = [...account.userIds][0] || "";
    const member = ticketReviewMember(firstUserId);
    const firstTicketId = [...account.ticketIds][0] || "";
    const ticket = (adminLiveDataState.tickets || []).find((item) => String(item.serverTicketId || item.id || "") === firstTicketId);
    records.push({
      id: `group-account-incomplete-${accountId}`,
      group: "issue",
      source: "1:2 연결 점검",
      member: member?.name || accountRow?.display_name || "1:2 회원 확인 필요",
      title: "파트너 연결 미완성",
      detail: `참여 회원 ${account.userIds.size}명 · 연결 회원권 ${account.ticketIds.size}개`,
      subDetail: "파트너 또는 회원권 연결을 확인해야 1:2 차감이 안전하게 처리됩니다.",
      statusLabel: "확인 필요",
      actionLabel: member ? "회원권 확인" : "운영 설정 확인",
      memberId: member?.id || null,
      ticketId: ticket?.serverTicketId || firstTicketId,
      actionView: member ? "" : "settings",
      priority: "urgent",
      urgentReason: "1:2 계정의 회원 또는 회원권 연결 수가 부족합니다.",
      sortAt: ticket?.serverUpdatedAt || "",
    });
  });

  const linkedTicketIds = new Set(linkContext.accountIdsByTicket.keys());
  (adminLiveDataState.tickets || [])
    .filter((ticket) => Number(ticket.groupSize || 1) === 2)
    .filter((ticket) => relevantStates.has(ticketReviewState(ticket)))
    .filter((ticket) => !linkedTicketIds.has(String(ticket.serverTicketId || ticket.id || "")))
    .forEach((ticket) => {
      const member = ticketReviewMember(ticket.serverUserId);
      records.push({
        id: `group-ticket-unlinked-${ticket.serverTicketId || ticket.id}`,
        group: "issue",
        source: "1:2 연결 점검",
        member: member?.name || ticket.member || "회원 확인 필요",
        title: "1:2 회원권 연결 없음",
        detail: `${getTicketDisplayProduct(ticket) || ticket.product || "1:2 회원권"} · ${getCoachName(ticket.coachId)}`,
        subDetail: "회원권은 유지하고 파트너 계정 연결만 확인해 주세요.",
        statusLabel: "확인 필요",
        actionLabel: member ? "회원권 확인" : "회원관리 확인",
        memberId: member?.id || null,
        ticketId: ticket.serverTicketId || "",
        actionView: member ? "" : "members",
        priority: "urgent",
        urgentReason: "사용 중인 1:2 회원권이 파트너 계정과 연결되지 않았습니다.",
        sortAt: ticket.serverUpdatedAt || ticket.expires || "",
      });
    });

  return records;
}

function adminRecordGroups() {
  const shared = operationalSharedData();
  const context = buildAdminRecordContext();
  const participantRecords = (adminLiveDataState.participantRecords || []).map((record) => (
    participantLessonRecord(record, context)
  ));
  const participantRecordLessonIds = new Set(
    (adminLiveDataState.participantRecords || []).map((record) => String(record.lesson_id || "")).filter(Boolean),
  );
  const records = [
    ...urgentOperationsRecords(),
    ...pendingLessonRecords(context),
    ...completedLessonRecordIssues(context),
    ...lessonNotes
      .filter((note) => !participantRecordLessonIds.has(String(note.serverLessonId || "")))
      .map(legacyNoteRecord),
    ...participantRecords,
    ...shared.lessonLogs.map(lessonLogRecord),
    ...shared.feedbackRequests.map(feedbackRecord),
    ...(adminLiveDataState.journalEntries || []).map((entry) => memberJournalRecord(entry, context)),
    ...ticketIntegrityReviewRecords(),
  ];
  const normalizedRecords = operationBranchRecords(records).map((record) => withRecordCoach(
    {
      ...record,
      pendingType: pendingRecordType(record),
    },
    record,
    context,
  ));
  const roleFilteredRecords = operationsRole() === "coach"
    ? normalizedRecords.filter((record) => (
      record.pendingType !== "payment"
      && recordBelongsToCurrentCoach(record)
    ))
    : normalizedRecords;
  return {
    pending: sortAdminRecords(roleFilteredRecords.filter((record) => record.group === "pending")),
    feedback: sortAdminRecords(roleFilteredRecords.filter((record) => record.group === "feedback")),
    done: sortAdminRecords(roleFilteredRecords.filter((record) => record.group === "done")),
    issue: sortAdminRecords(roleFilteredRecords.filter((record) => record.group === "issue")),
  };
}

function renderRecordFilters(records = []) {
  const coachSelect = $("#recordCoachFilter");
  if (coachSelect) {
    const availableCoachIds = new Set(records.map((record) => record.coachId).filter(Boolean));
    coachSelect.innerHTML = [
      '<option value="all">전체 코치</option>',
      ...coaches
        .filter((coach) => availableCoachIds.has(coach.id))
        .map((coach) => `<option value="${escapeHtml(coach.id)}">${escapeHtml(coach.name)}</option>`),
    ].join("");
    if (state.recordCoachFilter !== "all" && !availableCoachIds.has(state.recordCoachFilter)) {
      state.recordCoachFilter = "all";
    }
    coachSelect.value = state.recordCoachFilter;
  }
  const pendingTypeSelect = $("#recordPendingTypeFilter");
  if (pendingTypeSelect) {
    pendingTypeSelect.hidden = state.recordFilter !== "pending";
    pendingTypeSelect.value = state.recordPendingType;
  }
}

function renderNotes() {
  const target = $("#recordAuditRows");
  if (!target) return;
  const groups = adminRecordGroups();
  const activeFilter = ["pending", "feedback", "done", "issue"].includes(state.recordFilter) ? state.recordFilter : "pending";
  state.recordFilter = activeFilter;
  if (!["all", "lesson", "payment", "makeup", "feedback"].includes(state.recordPendingType)) state.recordPendingType = "all";
  if (!state.recordCoachFilter) state.recordCoachFilter = "all";
  if (typeof state.recordSearch !== "string") state.recordSearch = "";

  renderRecordFilters(Object.values(groups).flat());
  if ($("#recordSearch")) $("#recordSearch").value = state.recordSearch;
  const visibleGroups = Object.fromEntries(Object.entries(groups).map(([key, records]) => [
    key,
    state.recordCoachFilter === "all" ? records : records.filter((record) => record.coachId === state.recordCoachFilter),
  ]));

  $("#recordPendingCount").textContent = `${visibleGroups.pending.length}건`;
  $("#recordFeedbackCount").textContent = `${visibleGroups.feedback.length}건`;
  $("#recordDoneCount").textContent = `${visibleGroups.done.length}건`;
  $("#recordIssueCount").textContent = `${visibleGroups.issue.length}건`;
  $$("[data-record-filter]").forEach((button) => button.classList.toggle("is-active", button.dataset.recordFilter === activeFilter));

  const searchQuery = state.recordSearch.trim().toLowerCase();
  const visibleRecords = visibleGroups[activeFilter].filter((record) => (
    activeFilter !== "pending"
    || state.recordPendingType === "all"
    || record.pendingType === state.recordPendingType
  )).filter((record) => (
    !searchQuery
    || [record.member, record.title, record.coachName, record.source]
      .some((value) => String(value || "").toLowerCase().includes(searchQuery))
  ));
  const recordPageSize = 20;
  state.recordPage = normalizeDashboardPage(visibleRecords.length, state.recordPage, recordPageSize);
  const pageStart = state.recordPage * recordPageSize;
  const pageRecords = visibleRecords.slice(pageStart, pageStart + recordPageSize);
  const summary = $("#recordResultSummary");
  if (summary) {
    const first = visibleRecords.length ? pageStart + 1 : 0;
    const last = Math.min(pageStart + recordPageSize, visibleRecords.length);
    summary.textContent = `전체 ${visibleRecords.length}건 · ${first}-${last}건 표시`;
  }
  renderDashboardPager("#recordAuditPager", visibleRecords.length, state.recordPage, "records", recordPageSize);
  target.innerHTML = pageRecords
    .map(
      (record) => `
        <article class="record-audit-card ${record.group} ${record.priority === "urgent" ? "urgent" : ""}">
          <div>
            <span>${escapeHtml(record.source)} · ${escapeHtml(record.coachName || "미배정")}</span>
            <strong>${escapeHtml(record.member)} · ${escapeHtml(record.title)}</strong>
            ${record.urgentReason ? `<em class="record-urgent-reason">${escapeHtml(record.urgentReason)}</em>` : ""}
            <p>${escapeHtml(record.detail)}</p>
            <small>${escapeHtml(record.subDetail)}</small>
          </div>
          <aside>
            ${recordStatusBadge(record)}
            ${record.memberId ? `<button class="small-button" type="button" data-record-member-id="${escapeHtml(record.memberId)}" data-record-ticket-id="${escapeHtml(record.ticketId || "")}" aria-label="${escapeHtml(`${record.member} · ${record.title} · ${record.actionLabel}`)}">${escapeHtml(record.actionLabel)}</button>` : record.actionable ? `<button class="small-button" type="button" data-open-lesson-record="${escapeHtml(record.lessonId)}" aria-label="${escapeHtml(`${record.member} · ${record.title} · ${record.coachName || "코치 미배정"} · ${record.actionLabel}`)}">${escapeHtml(record.actionLabel)}</button>` : record.actionView ? `<button class="small-button" type="button" data-record-action-view="${escapeHtml(record.actionView)}" aria-label="${escapeHtml(`${record.member} · ${record.title} · ${record.coachName || "코치 미배정"} · ${record.actionLabel}`)}">${escapeHtml(record.actionLabel)}</button>` : record.mediaCount ? `<button class="ghost-button" type="button" data-open-journal-media="${escapeHtml(record.journalId)}" aria-label="${escapeHtml(`${record.member} · ${record.title} · ${record.coachName || "코치 미배정"} · ${record.actionLabel}`)}">${escapeHtml(record.actionLabel)}</button>` : `<b>${escapeHtml(record.actionLabel)}</b>`}
          </aside>
        </article>`,
    )
    .join("") || adminEmptyState({
      title: "해당 상태의 기록이 없습니다",
      reason: activeFilter === "pending"
        ? "수업 후 코멘트·커리큘럼·차감이 필요한 항목이 생기면 여기에 표시됩니다."
        : "필터를 바꾸면 다른 처리 상태의 기록을 확인할 수 있습니다.",
      action: { label: "오늘 시간표 확인", jump: "schedule", primary: false },
      compact: true,
    });
}

function closeLessonRecordModal() {
  const modal = $("#lessonRecordModal");
  if (modal) modal.hidden = true;
  Object.assign(lessonRecordEditorState, { lessonId: "", journalId: "", saving: false });
  $("#lessonRecordForm")?.reset();
  if ($("#lessonRecordMessage")) $("#lessonRecordMessage").textContent = "";
}

function updateLessonRecordCurriculumLink() {
  const selectedId = $("#lessonRecordCurriculum")?.value || "";
  const curriculum = adminCurriculumChoices().find((item) => item.value === selectedId);
  const link = $("#lessonRecordCurriculumLink");
  if (!link) return;
  link.hidden = selectedLessonRecordOutcome().startsWith("no_show") || !curriculum?.notionUrl;
  link.href = curriculum?.notionUrl || "#";
}

function selectedLessonRecordOutcome() {
  return document.querySelector('input[name="lessonRecordOutcome"]:checked')?.value || "completed_deduct";
}

function syncLessonRecordOutcomeUi() {
  const value = selectedLessonRecordOutcome();
  const noShow = value.startsWith("no_show");
  const deduct = value.endsWith("_deduct");
  const comment = $("#lessonRecordComment");
  const curriculum = $("#lessonRecordCurriculum");
  $("#lessonRecordCommentLabel").textContent = noShow ? "노쇼 사유" : "코치 코멘트";
  comment.placeholder = noShow ? "예: 연락 없이 불참" : "이번 수업에서 확인한 내용과 다음 연습 포인트를 5자 이상 작성해 주세요.";
  comment.minLength = noShow ? 2 : 5;
  curriculum.required = !noShow;
  curriculum.closest("label").hidden = noShow;
  $("#lessonRecordCurriculumLink").hidden = noShow || !$("#lessonRecordCurriculumLink").href;
  $("#saveLessonRecordButton").textContent = `${noShow ? "노쇼" : "완료"} 저장 · ${deduct ? "횟수 차감" : "차감 없음"}`;
}

function adminCurriculumChoices() {
  const refs = (adminLiveDataState.curriculumRefs || []).filter((item) => item.status === "active");
  const catalogSteps = window.TennisNoteCurriculumCatalog?.steps || [];
  const choices = catalogSteps.map((step) => {
    const ref = refs.find((item) => item.skill_label === step.id || item.title === step.title);
    return {
      value: ref?.id || `catalog:${step.id}`,
      label: `${step.trackTitle || step.category || step.level || "커리큘럼"} · ${step.title}`,
      notionUrl: step.notionUrl || ref?.notion_url || "",
      step,
    };
  });
  refs.forEach((ref) => {
    if (choices.some((item) => item.value === ref.id || item.step?.id === ref.skill_label)) return;
    choices.push({
      value: ref.id,
      label: `${ref.level_label || "커리큘럼"} · ${ref.title}`,
      notionUrl: ref.notion_url || "",
      step: null,
    });
  });
  return choices;
}

async function ensureAdminCurriculumRef(choiceValue) {
  if (!String(choiceValue).startsWith("catalog:")) return choiceValue;
  const code = String(choiceValue).slice("catalog:".length);
  const step = (window.TennisNoteCurriculumCatalog?.steps || []).find((item) => item.id === code);
  if (!step) throw new Error("curriculum_choice_not_found");
  return window.TennisNoteDataClient.rpc("tn_ensure_curriculum_ref", {
    target_code: step.id,
    target_level: `${step.trackTitle || step.category || "커리큘럼"} · ${step.stageLabel || step.level || "단계"}`,
    target_title: step.title,
    target_notion_url: step.notionUrl || "",
  });
}

function searchableAdminCurriculumChoice(choice) {
  const step = choice.step || {};
  return {
    ...step,
    id: step.id || choice.value,
    title: step.title || choice.label,
    trackTitle: step.trackTitle || step.category || choice.label,
    goal: step.goal || choice.label,
    __choiceValue: choice.value,
  };
}

function rankedAdminCurriculumChoices(choices, query) {
  if (!query) return choices;
  const search = window.TennisNoteCurriculumSearch;
  if (!search?.search) {
    const normalizedQuery = String(query).trim().toLocaleLowerCase("ko-KR");
    return choices.filter((item) => `${item.value} ${item.label}`.toLocaleLowerCase("ko-KR").includes(normalizedQuery));
  }
  const byValue = new Map(choices.map((choice) => [choice.value, choice]));
  return search.search(choices.map(searchableAdminCurriculumChoice), query, { limit: 24 })
    .map((result) => byValue.get(result.step.__choiceValue))
    .filter(Boolean);
}

function renderLessonRecordCurriculumSuggestions(choices, query) {
  const target = $("#lessonRecordCurriculumSuggestions");
  if (!target) return;
  if (!query) {
    target.hidden = true;
    target.innerHTML = "";
    return;
  }
  target.hidden = false;
  target.innerHTML = choices.length
    ? choices.map((choice, index) => {
      const step = choice.step || {};
      const detail = step.focus || step.goal || step.guide || "검색 결과에서 선택하면 다음 커리큘럼에 바로 반영됩니다.";
      const meta = [step.category || step.trackTitle, step.stageLabel || step.level].filter(Boolean).join(" · ");
      return `<button type="button" class="tn-curriculum-suggestion${index === 0 ? " is-active" : ""}" role="option" data-lesson-record-curriculum-choice="${escapeHtml(choice.value)}" data-curriculum-search-label="${escapeHtml(`${step.id || ""} ${step.title || choice.label}`.trim())}"><strong>${escapeHtml(choice.label)}</strong>${meta ? `<span>${escapeHtml(meta)}</span>` : ""}<small>${escapeHtml(detail)}</small></button>`;
    }).join("")
    : '<p class="tn-curriculum-suggestions-empty">일치하는 단계가 없습니다. 증상이나 동작을 다른 말로 입력해 보세요.</p>';
}

function filterLessonRecordCurriculumOptions() {
  const select = $("#lessonRecordCurriculum");
  if (!select) return;
  const selectedValue = select.value;
  const query = String($("#lessonRecordCurriculumSearch")?.value || "").trim();
  const choices = adminCurriculumChoices();
  const filtered = rankedAdminCurriculumChoices(choices, query);
  const selectedChoice = choices.find((item) => item.value === selectedValue);
  const visibleChoices = selectedChoice && !filtered.some((item) => item.value === selectedChoice.value)
    ? [selectedChoice, ...filtered]
    : filtered;
  select.innerHTML = `<option value="">${query && !filtered.length ? "검색 결과 없음" : "다음 커리큘럼 선택"}</option>${visibleChoices.map((item) => `<option value="${escapeHtml(item.value)}">${escapeHtml(item.label)}</option>`).join("")}`;
  if (selectedChoice) select.value = selectedValue;
  renderLessonRecordCurriculumSuggestions(filtered, query);
  updateLessonRecordCurriculumLink();
}

function openLessonRecordModal(lessonId) {
  const lesson = lessons.find((item) => item.serverLessonId === lessonId);
  const reviewableStatuses = new Set(["scheduled", "pending_change", "completed", "no_show"]);
  if (!lesson || !reviewableStatuses.has(String(lesson.serverStatus || ""))) {
    showToast("처리할 수업을 새로고침 후 다시 선택해 주세요.");
    return;
  }
  const ownRoleIds = currentOperationsCoachRoleIds();
  if (operationsRole() === "coach" && !ownRoleIds.has(lesson.coachRoleId)) {
    showToast("본인 담당 수업만 처리할 수 있습니다.");
    return;
  }
  const scheduleV2 = window.TennisNoteScheduleV2Admin;
  if (scheduleV2?.openLesson) {
    setView("schedule", { skipLock: true });
    void scheduleV2.openLesson({
      lessonId,
      lessonDate: lesson.lessonDate,
      mode: "outcome",
    }).then((opened) => {
      if (!opened && lesson.serverStatus === "scheduled") openLegacyLessonRecordModal(lessonId);
      else if (!opened) showToast("V2 기록에서 수업을 찾지 못했습니다. 새로고침 후 다시 선택해 주세요.");
    }).catch(() => {
      if (lesson.serverStatus === "scheduled") openLegacyLessonRecordModal(lessonId);
      else showToast("완료 기록을 불러오지 못했습니다. 새로고침 후 다시 선택해 주세요.");
    });
    return;
  }
  openLegacyLessonRecordModal(lessonId);
}

function openLegacyLessonRecordModal(lessonId) {
  const lesson = lessons.find((item) => item.serverLessonId === lessonId);
  if (!lesson || lesson.serverStatus !== "scheduled") {
    showToast("처리할 수업을 새로고침 후 다시 선택해 주세요.");
    return;
  }
  const ownRoleIds = currentOperationsCoachRoleIds();
  if (operationsRole() === "coach" && !ownRoleIds.has(lesson.coachRoleId)) {
    showToast("본인 담당 수업만 처리할 수 있습니다.");
    return;
  }
  const journal = (adminLiveDataState.journalEntries || [])
    .filter((entry) => entry.lesson_id === lessonId)
    .sort((left, right) => String(right.updated_at || right.created_at || "").localeCompare(String(left.updated_at || left.created_at || "")))[0] || null;
  const mediaCount = journal
    ? (adminLiveDataState.mediaFiles || []).filter((media) => media.journal_entry_id === journal.id).length
    : 0;
  Object.assign(lessonRecordEditorState, { lessonId, journalId: journal?.id || "", saving: false });
  $("#lessonRecordContext").innerHTML = `
    <strong>${escapeHtml(lesson.member)} · ${escapeHtml(lesson.lessonDate)} ${escapeHtml(lesson.time)}</strong>
    <span>${escapeHtml(getCoachName(lesson.coachId))} · ${escapeHtml(lesson.type)} ${Number(lesson.durationMinutes) || 20}분 · 잔여 ${Number(lesson.ticketRemaining) || 0}회</span>
    <p>${journal ? escapeHtml(journalBodySummary(journal.body)) : "회원 운동일지 미작성 · 코치 기록만으로 완료할 수 있습니다."}</p>
    ${mediaCount ? `<button class="ghost-button" type="button" data-open-journal-media="${escapeHtml(journal.id)}">사진·영상 ${mediaCount}개 보기</button>` : ""}`;
  const select = $("#lessonRecordCurriculum");
  const choices = adminCurriculumChoices();
  if ($("#lessonRecordCurriculumSearch")) $("#lessonRecordCurriculumSearch").value = "";
  if ($("#lessonRecordCurriculumSuggestions")) $("#lessonRecordCurriculumSuggestions").hidden = true;
  select.innerHTML = `<option value="">다음 커리큘럼 선택</option>${choices.map((item) => `<option value="${escapeHtml(item.value)}">${escapeHtml(item.label)}</option>`).join("")}`;
  $("#lessonRecordComment").value = "";
  const defaultOutcome = document.querySelector('input[name="lessonRecordOutcome"][value="completed_deduct"]');
  if (defaultOutcome) defaultOutcome.checked = true;
  $("#lessonRecordMessage").textContent = choices.length ? "" : "연결된 커리큘럼이 없습니다.";
  $("#lessonRecordModal").hidden = false;
  syncLessonRecordOutcomeUi();
  updateLessonRecordCurriculumLink();
  $("#lessonRecordComment").focus();
}

function lessonRecordErrorMessage(error) {
  let code = error?.payload?.message || error?.payload?.code || error?.message || "server_error";
  if (typeof code === "string" && code.trim().startsWith("{")) {
    try {
      const parsed = JSON.parse(code);
      code = parsed.message || parsed.code || code;
    } catch {
      // Keep the server message when it is not valid JSON.
    }
  }
  return ({
    lesson_complete_comment_too_short: "코치 코멘트는 5자 이상 작성해 주세요.",
    lesson_complete_comment_too_generic: "짧은 칭찬이나 확인 문구 대신 이번 수업 내용을 작성해 주세요.",
    lesson_complete_comment_recent_duplicate: "최근 수업과 같은 코멘트입니다. 이번 수업 내용을 새로 작성해 주세요.",
    lesson_complete_forbidden: "이 수업을 처리할 권한이 없습니다.",
    lesson_complete_status_invalid: "이미 완료·취소된 수업입니다. 새로고침 후 확인해 주세요.",
    lesson_complete_ticket_unavailable: "사용 가능한 회원권 횟수가 없습니다.",
  })[code] || "서버 저장에 실패했습니다. 새로고침 후 다시 시도해 주세요.";
}

function applyAdminCommentDraft(keywordSelector, commentSelector) {
  const keywordInput = $(keywordSelector);
  const commentInput = $(commentSelector);
  const generator = window.TennisNoteCommentDraft;
  if (!keywordInput || !commentInput || !generator?.generate) {
    showToast("코멘트 초안 기능을 불러오지 못했습니다.");
    return;
  }
  const result = generator.generate(keywordInput.value);
  if (!result.ok) {
    showToast(result.message);
    keywordInput.focus();
    return;
  }
  commentInput.value = result.comment;
  commentInput.dispatchEvent(new Event("input", { bubbles: true }));
  commentInput.focus();
  showToast("세부 코멘트 초안을 만들었습니다. 내용을 확인한 뒤 저장해 주세요.");
}

async function saveLessonRecord(event) {
  event.preventDefault();
  if (lessonRecordEditorState.saving) return;
  const comment = $("#lessonRecordComment").value.trim();
  const curriculumId = $("#lessonRecordCurriculum").value;
  const outcomeValue = selectedLessonRecordOutcome();
  const noShow = outcomeValue.startsWith("no_show");
  const deduct = outcomeValue.endsWith("_deduct");
  const message = $("#lessonRecordMessage");
  if (comment.length < (noShow ? 2 : 5) || (!noShow && !curriculumId)) {
    message.textContent = comment.length < (noShow ? 2 : 5)
      ? noShow ? "노쇼 사유를 2자 이상 작성해 주세요." : "코치 코멘트를 5자 이상 작성해 주세요."
      : "다음 커리큘럼을 선택해 주세요.";
    return;
  }
  const client = window.TennisNoteDataClient;
  if (!client?.rpc || !operationsAccessReady()) {
    message.textContent = "대표 관리자 계정 로그인 상태를 확인해 주세요.";
    return;
  }
  lessonRecordEditorState.saving = true;
  const button = $("#saveLessonRecordButton");
  button.disabled = true;
  button.textContent = "서버 저장 중";
  message.textContent = "";
  try {
    const curriculumRefId = noShow ? null : await ensureAdminCurriculumRef(curriculumId);
    const result = await client.rpc("tn_process_lesson_outcome", {
      target_lesson_id: lessonRecordEditorState.lessonId,
      target_outcome: noShow ? "no_show" : "completed",
      target_deduct: deduct,
      target_note: comment,
      target_next_curriculum_ref_id: curriculumRefId,
      target_member_journal_id: lessonRecordEditorState.journalId || null,
    });
    window.TennisNoteInputGuard?.markSaved?.("#lessonRecordModal");
    closeLessonRecordModal();
    state.recordFilter = "done";
    await syncAdminLiveData();
    setView("notes", { skipLock: true });
    showToast(result?.idempotent ? "이미 처리된 수업을 확인했습니다." : `${noShow ? "노쇼" : "수업 완료"} 처리와 ${deduct ? "횟수 차감" : "미차감 기록"}이 저장됐습니다.`);
  } catch (error) {
    message.textContent = lessonRecordErrorMessage(error);
  } finally {
    lessonRecordEditorState.saving = false;
    button.disabled = false;
    syncLessonRecordOutcomeUi();
  }
}

async function openJournalMedia(journalId) {
  const files = (adminLiveDataState.mediaFiles || []).filter((media) => media.journal_entry_id === journalId);
  if (!files.length) {
    showToast("첨부된 사진이나 영상이 없습니다.");
    return;
  }
  const preview = window.open("", "_blank");
  try {
    const blob = await window.TennisNoteDataClient.downloadObject("tennisnote-journal-media", files[0].storage_path);
    const url = URL.createObjectURL(blob);
    if (preview) preview.location.href = url;
    else window.open(url, "_blank");
    if (files.length > 1) showToast(`첫 첨부를 열었습니다. 전체 ${files.length}개입니다.`);
  } catch {
    preview?.close();
    showToast("첨부파일을 불러오지 못했습니다.");
  }
}

